	["A letter from the Scarshield Quartermaster in Blackrock Spire sends you to the orb behind General Drakkisath, which opens Blackwing Lair."] = "Ein Brief des Rüstmeisters der Schmetterschilde in der Schwarzfelsspitze schickt Euch zur Kugel hinter General Drakkisath, die den Pechschwingenhort öffnet.",
	["A line from your story under each chapter title and another after its moments, told in the tone you picked on the Story tab. Level view only."] = "Eine Zeile aus Eurer Geschichte unter jedem Kapiteltitel und eine weitere nach seinen Momenten, erzählt im Ton, den Ihr im Reiter Geschichte gewählt habt. Nur in der Stufenansicht.",
	["A little high for you: a level %d quest."] = "Etwas hoch für Euch: eine Quest der Stufe %d.",
	["A little high for you: it starts at level %d."] = "Etwas hoch für Euch: beginnt auf Stufe %d.",
	["A little low for you: it is %d-%d."] = "Etwas niedrig für Euch: Stufe %d-%d.",
	["A long break"] = "Eine lange Pause",
	["A milestone to look forward to."] = "Ein Meilenstein, auf den Ihr Euch freuen könnt.",
	["A moment in your journal"] = "Ein Moment in Eurem Tagebuch",
	["A new goal"] = "Ein neues Ziel",
	["A note"] = "Eine Notiz",
	["A note remembers where and when you wrote it, and it can remind you later."] = "Eine Notiz merkt sich, wo und wann Ihr sie geschrieben habt, und kann Euch später erinnern.",
	["A note remembers where and when you wrote it. It can remind you later."] = "Eine Notiz merkt sich, wo und wann Ihr sie geschrieben habt. Sie kann Euch später erinnern.",
	["A one-time reminder moves to the archive once it has fired or you mark it done."] = "Eine einmalige Erinnerung wandert ins Archiv, sobald sie ausgelöst wurde oder Ihr sie als erledigt markiert.",
	["A page of My Adventure"] = "Eine Seite von Mein Abenteuer",
	["A pin on the world map for each giver of the quests left in the zone the map shows. Hover it for the quests, click it for a waypoint. The map's EldoUI pin switch hides it with the other pins."] = "Eine Markierung auf der Weltkarte für jeden Questgeber der Quests, die im gezeigten Gebiet noch offen sind. Zeigt darauf für die Quests, klickt für einen Wegpunkt. Der EldoUI-Markierungsschalter der Karte blendet sie mit den anderen Markierungen aus.",
	["A pin where the next step of each attunement you are on starts. Click it for the arrow."] = "Eine Markierung dort, wo der nächste Schritt jeder Eurer Einstimmungen beginnt. Klickt darauf für den Pfeil.",
	["A place in your journal"] = "Ein Ort in Eurem Tagebuch",
	["A quest counts once you both have it and one of its objectives moves forward while you are grouped."] = "Eine Quest zählt, sobald Ihr sie beide habt und eines ihrer Questziele vorankommt, während Ihr in einer Gruppe seid.",
	["A quest of this event."] = "Eine Quest dieses Ereignisses.",
	["A quest outside dungeons, or a creature and what it drops."] = "Eine Quest außerhalb von Dungeons, oder eine Kreatur und was sie fallen lässt.",
	["A quest that needs this standing."] = "Eine Quest, die diesen Rang erfordert.",
	["A quest that rewards the recipe."] = "Eine Quest, die das Rezept als Belohnung gibt.",
	["A reached goal moves to the archive instead of staying in the Reached list."] = "Ein erreichtes Ziel wandert ins Archiv, statt in der Liste „Erreicht“ zu bleiben.",
	["A reminder"] = "Eine Erinnerung",
	["A row each time you die, with the place."] = "Eine Zeile bei jedem Tod, mit dem Ort.",
	["A row each time you learn a spell or a new rank."] = "Eine Zeile, wann immer Ihr einen Zauber oder einen neuen Rang erlernt.",
	["A row for each boss you kill in a dungeon or raid, with a keepsake for the first kill."] = "Eine Zeile für jeden Boss, den Ihr in einem Dungeon oder Schlachtzug tötet, mit einem Andenken für den ersten Sieg.",
	["A row for each flight path you learn."] = "Eine Zeile für jede Flugroute, die Ihr erlernt.",
	["A row for each recipe you learn."] = "Eine Zeile für jedes Rezept, das Ihr erlernt.",
	["A row when you equip an item that is better than the one it replaced."] = "Eine Zeile, wenn Ihr einen Gegenstand anlegt, der besser ist als der, den er ersetzt.",
	["A row when you reset your talents."] = "Eine Zeile, wenn Ihr Eure Talente zurücksetzt.",
	["A row when you set a goal and when you reach it."] = "Eine Zeile, wenn Ihr ein Ziel setzt und wenn Ihr es erreicht.",
	["A sample step"] = "Ein Beispielschritt",
	["A scroll above the name."] = "Eine Schriftrolle über dem Namen.",
	["A scroll in a bronze frame above the name, to match the WoW Forever art style."] = "Eine Schriftrolle im Bronzerahmen über dem Namen, passend zum Kunststil von WoW Forever.",
	["A scroll, the quest giver's exclamation mark, a dot in your accent color, a scroll in a bronze frame, or a yellow square with a mark that reads for every kind of color blindness."] = "Eine Schriftrolle, das Ausrufezeichen des Questgebers, ein Punkt in Eurer Akzentfarbe, eine Schriftrolle im Bronzerahmen oder ein gelbes Quadrat mit einem Zeichen, das bei jeder Art von Farbenblindheit lesbar bleibt.",
	["A short card when you enter a zone or a dungeon: your quests there, rares, your notes and your last run. Off in combat."] = "Eine kurze Karte, wenn Ihr eine Zone oder einen Dungeon betretet: Eure Quests dort, seltene Gegner, Eure Notizen und Euer letzter Durchlauf. Im Kampf aus.",
	["A short card when you save a note."] = "Eine kurze Karte, wenn Ihr eine Notiz speichert.",
	["A short summary of the session during the logout countdown, also kept as a row in the Day view."] = "Eine kurze Zusammenfassung der Sitzung während des Logout-Countdowns, auch als Zeile in der Tagesansicht gespeichert.",
	["A short tour of My Adventure."] = "Eine kurze Tour durch Mein Abenteuer.",
	["A small dot in your accent color left of the bar."] = "Ein kleiner Punkt in Eurer Akzentfarbe links vom Balken.",
	["A small icon on the nameplate of a creature that can drop a quest starter. Needs EldoUI's Nameplates module."] = "Ein kleines Symbol auf der Namensplakette einer Kreatur, die einen Gegenstand fallen lassen kann, der eine Quest beginnt. Benötigt das Modul Nameplates von EldoUI.",
	["A small mark after each sentence; hover it to see the facts the sentence comes from."] = "Eine kleine Markierung nach jedem Satz; fahrt mit der Maus darüber, um die Fakten zu sehen, aus denen der Satz stammt.",
	["A solid dark page with no ornaments, numbers first."] = "Eine schlichte dunkle Seite ohne Verzierungen, Zahlen zuerst.",
	["A step of %s is here: %s."] = "Ein Schritt von %s ist hier: %s.",
	["A step of %s is inside: %s."] = "Ein Schritt von %s ist drinnen: %s.",
	["A string with this character's Best in Slot, plan sets, spec and talents (no name or realm) to share."] = "Ein Text mit Best in Slot, Plansets, Spezialisierung und Talenten dieses Charakters (ohne Namen oder Realm) zum Teilen.",
	["A strip over the chapters with a mark for each level and its big moments. Click a level to open its chapter. Shown in the level view while no search or filter is on."] = "Ein Streifen über den Kapiteln mit einer Marke für jede Stufe und ihre großen Momente. Klickt auf eine Stufe, um ihr Kapitel zu öffnen. In der Stufenansicht sichtbar, solange keine Suche und kein Filter aktiv ist.",
	["A to-do you check off yourself."] = "Eine Aufgabe, die Ihr selbst abhakt.",
	["A toast or banner, a sound and a chat line when a wished item is in a loot window or a roll, or drops in the dungeon you enter. Set them in /eui > Loot Guide."] = "Ein Toast oder Banner, ein Ton und eine Chatzeile, wenn ein gewünschter Gegenstand in einem Beutefenster oder einem Wurf ist oder in dem Dungeon fällt, den Ihr betretet. Einstellbar unter /eui > Loot Guide.",
	["A toast when you finish a step or a whole attunement. Nothing is posted to chat."] = "Ein Toast, wenn Ihr einen Schritt oder eine ganze Einstimmung abschließt. Im Chat wird nichts gepostet.",
	["A trainer who teaches this recipe."] = "Ein Lehrer, der dieses Rezept lehrt.",
	["A vendor during this event."] = "Ein Händler während dieses Ereignisses.",
	["A vendor for these rewards."] = "Ein Händler für diese Belohnungen.",
	["A vendor who sells the recipe."] = "Ein Händler, der das Rezept verkauft.",
	["A yellow square with a mark above the name; the shape carries it too."] = "Ein gelbes Quadrat mit einem Zeichen über dem Namen; auch die Form zeigt es an.",
	["A zone, or a spot inside one like Frostmane Hold."] = "Eine Zone oder ein Ort darin, etwa Frostmähnenfeste.",
	["Abandoned"] = "Abgebrochen",
	["Abandoned quests"] = "Abgebrochene Quests",
	["Abandoned, failed, or removed by the game. The journal only lists them; nothing is picked up again for you."] = "Abgebrochen, fehlgeschlagen oder vom Spiel entfernt. Das Tagebuch listet sie nur auf; nichts wird für Euch erneut angenommen.",
	["About %s of play at your recent pace. It counts your own last levels only."] = "Etwa %s Spielzeit bei Eurem jüngsten Tempo. Es zählt nur Eure eigenen letzten Stufen.",
	["About %s per kill."] = "Etwa %s pro Sieg.",
	["About as good as what you wear"] = "Etwa so gut wie das, was Ihr tragt",
	["About the same"] = "Etwa gleich",
	["About this zone"] = "Über diese Zone",
	["Above the name"] = "Über dem Namen",
	["Accept merges it into this character's journal: nothing is lost, and a backup is taken first."] = "Annehmen führt es mit dem Tagebuch dieses Charakters zusammen: Nichts geht verloren, und vorher wird eine Sicherung angelegt.",
	["Accept merges them into this character's runs: nothing is lost, and a backup is taken first."] = "Annehmen führt sie mit den Durchläufen dieses Charakters zusammen: Nichts geht verloren, und vorher wird eine Sicherung angelegt.",
	["Accessories"] = "Accessoires",
	["Active goals"] = "Aktive Ziele",
	["Active now"] = "Jetzt aktiv",
	["Active now and start dates: from the game's calendar."] = "Jetzt aktiv und Starttermine: laut Kalender des Spiels.",
	["Add my BiS"] = "Mein BiS hinzufügen",
	["Add to wishlist"] = "Zur Wunschliste hinzufügen",
	["Add wishlist note"] = "Wunschlisten-Notiz hinzufügen",
	["Added %d PvP items from your wishlist to the planner."] = "%d PvP-Gegenstände von Eurer Wunschliste zum Planer hinzugefügt.",
	["Added %d best-in-slot items to your wishlist."] = "%d Best-in-Slot-Gegenstände zu Eurer Wunschliste hinzugefügt.",
	["Added %d items to %s."] = { one = "%d Gegenstand zu %s hinzugefügt.", other = "%d Gegenstände zu %s hinzugefügt." },
	["Added %d pieces of %s to your wishlist."] = { one = "%d Teil von %s zu Eurer Wunschliste hinzugefügt.", other = "%d Teile von %s zu Eurer Wunschliste hinzugefügt." },
	["Added %s to %s."] = "%s zu %s hinzugefügt.",
	["Adds a Need, Greed or Pass word to that box. It is a label only and never rolls for you."] = "Fügt diesem Feld ein Wort für Bedarf, Gier oder Passen hinzu. Es ist nur ein Hinweis und würfelt nie für Euch.",
	["Adds a Quests line (done of total) to Zone Info's world map tooltip when you hover a zone. Needs the Zone Info module."] = "Fügt dem Weltkarten-Tooltip von Zone Info eine Zeile Quests (erledigt von gesamt) hinzu, wenn Ihr auf ein Gebiet zeigt. Benötigt das Modul Zone Info.",
	["Adds a button to the toast that posts one line in guild chat when you click it."] = "Fügt dem Toast einen Knopf hinzu, der beim Klicken eine Zeile im Gildenchat postet.",
	["Adds it to your goals, so the tracker and the Goals page follow it."] = "Fügt es Euren Zielen hinzu, damit der Tracker und die Seite „Ziele“ es verfolgen.",
	["Adds the PvP rewards on your active wishlist to the planner."] = "Fügt die PvP-Belohnungen Eurer aktiven Wunschliste dem Planer hinzu.",
	["Adds the best-in-slot items for your spec that you do not own and have not wished for yet."] = "Fügt die Best-in-Slot-Gegenstände Eurer Spezialisierung hinzu, die Ihr weder besitzt noch bereits gewünscht habt.",
	["Adds the item to your active wishlist, or takes it off every list on show."] = "Fügt den Gegenstand Eurer aktiven Wunschliste hinzu oder entfernt ihn von jeder angezeigten Liste.",
	["Adds the item to your active wishlist, or takes it off."] = "Fügt den Gegenstand Eurer aktiven Wunschliste hinzu oder entfernt ihn.",
	["Advice only: you roll yourself."] = "Nur ein Rat: Ihr würfelt selbst.",
	["After 12 hours away"] = "Nach 12 Stunden Abwesenheit",
	["After 4 hours away"] = "Nach 4 Stunden Abwesenheit",
	["After a break, Today starts with a card about your last session: where you were, your level, and its best moment. Never: no card."] = "Nach einer Pause beginnt „Heute“ mit einer Karte zu Eurer letzten Sitzung: wo Ihr wart, Eure Stufe und ihr bester Moment. Nie: keine Karte.",
	["After a day away"] = "Nach einem Tag Abwesenheit",
	["After an hour away"] = "Nach einer Stunde Abwesenheit",
	["After: %s"] = "Danach: %s",
	["Afterwards"] = "Danach",
	["Ahn'Qiraj sets"] = "Ahn'Qiraj-Sets",
	["Aimed Shot, Multi-Shot and Arcane Shot"] = "Gezielter Schuss, Mehrfachschuss und Arkaner Schuss",
	["Alcaz Prison"] = "Alcaz Prison",
	["Alchemy"] = "Alchemie",
	["Alert card with a button"] = "Hinweiskarte mit Schaltfläche",
	["Alert sound"] = "Alarmton",
	["Alerts off"] = "Hinweise aus",
	["Alerts on (%s)"] = "Hinweise an (%s)",
