	["Already worn"] = "Bereits getragen",
	["Also good"] = "Auch gut",
	["Also list and count quests you can do again."] = "Auch wiederholbare Quests auflisten und zählen.",
	["Also lists items above your level, to plan ahead. Saved for this character."] = "Listet auch Gegenstände über Eurer Stufe, um vorauszuplanen. Für diesen Charakter gespeichert.",
	["Also lists recipes that no longer give you skill points."] = "Listet auch Rezepte, die Euch keine Fertigkeitspunkte mehr geben.",
	["Also lists the other faction's rewards."] = "Listet auch die Belohnungen der anderen Fraktion.",
	["Also pin givers whose quests need a higher level."] = "Auch Questgeber markieren, deren Quests eine höhere Stufe brauchen.",
	["Also pin givers whose quests open after another quest."] = "Auch Questgeber markieren, deren Quests sich erst nach einer anderen Quest öffnen.",
	["Also rare mobs and random world drops."] = "Auch seltene Gegner und zufällige Weltbeute.",
	["Also star items from"] = "Auch Gegenstände markieren aus",
	["Also this level: %s"] = "Auch auf dieser Stufe: %s",
	["Also with %s"] = "Auch mit %s",
	["Alt-click an item"] = "Alt-Klick auf einen Gegenstand",
	["Alterac Valley"] = "Alteractal",
	["Always my name"] = "Immer mein Name",
	["An attunement or key, step by step as the Attunements tab tracks it."] = "Eine Einstimmung oder ein Schlüssel, Schritt für Schritt, wie der Reiter Einstimmungen sie verfolgt.",
	["An item"] = "Ein Gegenstand",
	["An item from your wishlist. Reached once you have it, worn, in your bags, or in the bank."] = "Ein Gegenstand von Eurer Wunschliste. Erreicht, sobald Ihr ihn habt: angelegt, in den Taschen oder in der Bank.",
	["And %d more the Loot Guide's quest data has no name for."] = { one = "Und %d weitere, für die die Questdaten des Loot Guide keinen Namen haben.", other = "Und %d weitere, für die die Questdaten des Loot Guide keinen Namen haben." },
	["Announced"] = "Angekündigt",
	["Any creature that gives experience."] = "Jede Kreatur, die Erfahrung gibt.",
