	["Armor too light for a tank"] = "Rüstung zu leicht für einen Tank",
	["Armor, weapons, consumables or the rest."] = "Rüstung, Waffen, Verbrauchsgüter oder der Rest.",
	["Arms the reminder again, from where you are now."] = "Stellt die Erinnerung erneut ein, ab Eurem jetzigen Standort.",
	["Arms: Mortal Strike"] = "Waffen: Tödlicher Stoß",
	["Arrival and dungeon briefs"] = "Ankunfts- und Dungeonkarten",
	["As of that character's last login."] = "Stand des letzten Logins dieses Charakters.",
	["As they happen"] = "Sobald sie passieren",
	["Ask me: a toast lets you send your progress with one click. Never: requests are ignored."] = "Mich fragen: Ein Toast lässt Euch Euren Fortschritt mit einem Klick senden. Nie: Anfragen werden ignoriert.",
	["Ask my group"] = "Meine Gruppe fragen",
	["Ask the guild"] = "Die Gilde fragen",
	["Asks your guild. Members who use EldoUI get a toast and choose whether to answer."] = "Fragt Eure Gilde. Mitglieder mit EldoUI bekommen einen Toast und entscheiden selbst, ob sie antworten.",
	["Asks your party or raid. Members who use EldoUI get a toast and choose whether to answer."] = "Fragt Eure Gruppe oder Euren Schlachtzug. Mitglieder mit EldoUI bekommen einen Toast und entscheiden selbst, ob sie antworten.",
	["At %s"] = "Bei %s",
	["At %s %s a week (typed in the settings)."] = "Bei %s %s pro Woche (in den Einstellungen eingetragen).",
	["At a flight master"] = "Bei einem Flugmeister",
	["At a mailbox"] = "An einem Briefkasten",
	["At a trainer"] = "Bei einem Lehrer",
	["At a vendor"] = "Bei einem Händler",
	["At an inn"] = "In einem Gasthaus",
	["At least one page stays on."] = "Mindestens eine Seite bleibt an.",
	["At level %d"] = "Auf Stufe %d",
	["At level %d: %s opens."] = "Auf Stufe %d: %s öffnet sich.",
	["At the auction house"] = "Im Auktionshaus",
	["At the bank"] = "In der Bank",
	["At your recent weekly %s: %s."] = "Bei Eurem jüngsten Wochenwert von %s: %s.",
	["Atlas"] = "Atlas",
	["Attuned"] = "Eingestimmt",
	["Attuned: %s"] = "Eingestimmt: %s",
	["Attunement"] = "Einstimmung",
	["Attunement complete"] = "Einstimmung abgeschlossen",
	["Attunement line in the Journal"] = "Einstimmungszeile im Tagebuch",
	["Attunement lines on item and character tooltips have their own switches on the Tooltip page."] = "Einstimmungszeilen in Gegenstands- und Charaktertooltips haben eigene Schalter auf der Seite Tooltip.",
	["Attunement · %d of %d steps"] = { one = "Einstimmung · %d von %d Schritt", other = "Einstimmung · %d von %d Schritten" },
	["Attunement: %d of %d steps"] = { one = "Einstimmung: %d von %d Schritt", other = "Einstimmung: %d von %d Schritten" },
	["Attunements"] = "Einstimmungen",
	["Attunements and keys of each character, as of its last login."] = "Einstimmungen und Schlüssel jedes Charakters, Stand seines letzten Logins.",
	["Attunements asked"] = "Einstimmungen erfragt",
	["Attunements check"] = "Einstimmungsprüfung",
	["Attunements data"] = "Einstimmungsdaten",
	["Attunements is off"] = "Einstimmungen ist aus",
	["Attunements probe"] = "Einstimmungstest",
	["Attunements, keys and dungeon quest chains as a Loot Guide tab. Progress comes from your quest log, bags and reputation."] = "Einstimmungen, Schlüssel und Dungeon-Questreihen als Reiter im Loot Guide. Der Fortschritt kommt aus Eurem Questlog, Euren Taschen und Eurem Ruf.",
	["Attunements, keys and dungeon quest chains as a tab in the Loot Guide: every step, what you have done, what comes next, and which of your characters are ready."] = "Einstimmungen, Schlüssel und Dungeon-Questreihen als Reiter im Loot Guide: jeder Schritt, was Ihr erledigt habt, was als Nächstes kommt und welche Eurer Charaktere bereit sind.",
	["Attunements, keys and dungeon quest chains: every step, what you have done and what comes next."] = "Einstimmungen, Schlüssel und Dungeon-Questreihen: jeder Schritt, was Ihr erledigt habt und was als Nächstes kommt.",
	["Attunements: characters"] = "Einstimmungen: Charaktere",
	["Attunements: items"] = "Einstimmungen: Gegenstände",
	["Auto"] = "Autom.",
	["Auto Shot"] = "Automatischer Schuss",
	["Back after %d days away"] = { one = "Zurück nach %d Tag Abwesenheit", other = "Zurück nach %d Tagen Abwesenheit" },
	["Back to realistic"] = "Zurück zu realistisch",
	["Back to search"] = "Zurück zur Suche",
	["Back to the goal kinds."] = "Zurück zu den Zielarten.",
	["Back to the list"] = "Zurück zur Liste",
	["Back to the quests you handed in."] = "Zurück zu den abgegebenen Quests.",
	["Back to your goals."] = "Zurück zu Euren Zielen.",
	["Back to your notes."] = "Zurück zu Euren Notizen.",
	["Back up"] = "Sichern",
	["Back up now"] = "Jetzt sichern",
	["Backed up: %s. It is on disk after your next logout or /reload."] = "Gesichert: %s. Nach Eurem nächsten Logout oder /reload liegt es auf der Festplatte.",
	["Backups are copies of this journal in your saved data. The game writes them to disk when you log out or /reload."] = "Sicherungen sind Kopien dieses Tagebuchs in Euren gespeicherten Daten. Das Spiel schreibt sie auf die Festplatte, wenn Ihr Euch ausloggt oder /reload nutzt.",
	["Backups are not loaded."] = "Sicherungen sind nicht geladen.",
	["Backups of this journal"] = "Sicherungen dieses Tagebuchs",
	["Backups of your runs"] = "Sicherungen Eurer Durchläufe",
	["Backups to keep"] = "Aufzubewahrende Sicherungen",
	["Bag space, repairs, food and water, ammo and hearthstone on the trip card. Nothing is bought or used."] = "Taschenplatz, Reparaturen, Essen und Wasser, Munition und Ruhestein auf der Reisekarte. Nichts wird gekauft oder benutzt.",
	["Balanced"] = "Ausgewogen",
	["Balanced, Leveling (zones and chains), Dungeons (dungeons, prep and attunements) or Collecting (reputation, rares and goals)."] = "Ausgewogen, Stufenaufstieg (Zonen und Questreihen), Dungeons (Dungeons, Vorbereitung und Einstimmungen) oder Sammeln (Ruf, seltene Gegner und Ziele).",
