	["Beaten %s"] = "Besiegt: %s",
	["Became a student of %s"] = "Schüler von %s geworden",
	["Before %s: %d things to sort"] = { one = "Vor %s: %d Sache zu erledigen", other = "Vor %s: %d Sachen zu erledigen" },
	["Before the first chapter"] = "Vor dem ersten Kapitel",
	["Before the journal"] = "Vor dem Tagebuch",
	["Before the journal knew your level"] = "Bevor das Tagebuch Eure Stufe kannte",
	["Before the journal: not recorded."] = "Vor dem Tagebuch: nicht aufgezeichnet.",
	["Before you go"] = "Bevor Ihr aufbrecht",
	["Before you go, getting in, inside, getting there, and afterward: the whole trip in one list."] = "Bevor Ihr aufbrecht, Hineinkommen, Drinnen, Anreise und Danach: die ganze Reise in einer Liste.",
