	["Each boss is added here when you defeat it, with the items you see it drop."] = "Jeder Boss erscheint hier, sobald Ihr ihn besiegt, mit den Gegenständen, die Ihr ihn fallen seht.",
	["Each dungeon run with its time, dungeon quests and battlegrounds won or lost."] = "Jeder Dungeondurchlauf mit seiner Zeit, Dungeonquests und gewonnene oder verlorene Schlachtfelder.",
	["Each quest you hand in is written here, with where and when."] = "Jede abgegebene Quest wird hier notiert, mit Ort und Zeit.",
	["Each run you make here is written down with its time, bosses, and company."] = "Jeder Durchlauf hier wird mit Zeit, Bossen und Begleitung notiert.",
	["Earlier attunements"] = "Frühere Einstimmungen",
	["Earlier moments"] = "Frühere Momente",
	["Earn %s gold"] = "%s Gold verdienen",
	["Earn a standing"] = "Einen Rang erreichen",
	["Earn gold"] = "Gold verdienen",
	["Earned %s"] = "%s verdient",
	["Edit"] = "Bearbeiten",
	["Edit the note"] = "Die Notiz bearbeiten",
	["Edit wishlist note"] = "Wunschlisten-Notiz bearbeiten",
	["Editing a note from %s"] = "Bearbeite eine Notiz von %s",
	["EldoUI already knew %d moments of yours from %s: they are on your Journey."] = { one = "EldoUI kannte bereits %d Moment von Euch aus %s: Er steht in Eurer Reise.", other = "EldoUI kannte bereits %d Momente von Euch aus %s: Sie stehen in Eurer Reise." },
	["EldoUI already knew %d moments of yours from its other records: they are on your Journey."] = { one = "EldoUI kannte bereits %d Moment von Euch aus seinen anderen Aufzeichnungen: Er steht in Eurer Reise.", other = "EldoUI kannte bereits %d Momente von Euch aus seinen anderen Aufzeichnungen: Sie stehen in Eurer Reise." },
	["EldoUI_LootData"] = "EldoUI_LootData",
	["EldoUI_LootData could not load"] = "EldoUI_LootData konnte nicht geladen werden",
	["EldoUI_LootData is not installed"] = "EldoUI_LootData ist nicht installiert",
	["EldoUI_LootData is switched off in the addon list"] = "EldoUI_LootData ist in der Addon-Liste ausgeschaltet",
	["EldoUI_LootData is switched off in the addon list. Turn it on to see quest chains."] = "EldoUI_LootData ist in der Addon-Liste ausgeschaltet. Schaltet es ein, um Questreihen zu sehen.",
	["EldoUI_LootData is too new or too old for this EldoUI"] = "EldoUI_LootData ist zu neu oder zu alt für dieses EldoUI",
	["EldoUI_LootData loads a few seconds after login"] = "EldoUI_LootData lädt einige Sekunden nach dem Login",
	["EldoUI_LootSim could not load. Check that it is in Interface\\AddOns next to EldoUI."] = "EldoUI_LootSim konnte nicht geladen werden. Prüft, dass es in Interface\\AddOns neben EldoUI liegt.",
	["EldoUI_LootSim is switched off in the addon list."] = "EldoUI_LootSim ist in der Addon-Liste ausgeschaltet.",
	["Emboldened seals"] = "Ermutigte Siegel",
	["Emptied the list %s."] = "Die Liste %s ist jetzt leer.",
	["Empties the set."] = "Leert das Set.",
	["Empty"] = "Leer",
	["Empty slot"] = "Leerer Platz",
	["Empty slot: click to pick"] = "Leerer Platz: zum Wählen klicken",
	["Empty the list on show. The other lists stay. Asks first."] = "Leert die angezeigte Liste. Die anderen Listen bleiben. Fragt vorher nach.",
	["Empty the planner. Asks first."] = "Leert den Planer. Fragt vorher nach.",
	["Enchanting"] = "Verzauberkunst",
	["Ends"] = "Endet",
	["Ends at %s"] = "Endet um %s",
	["Ends the tour. Start it again with /eui tour journal."] = "Beendet die Tour. Startet sie wieder mit /eui tour journal.",
	["Ends the tour. Start it again with Start tour on the Loot Guide settings page or /eui tour lootguide."] = "Beendet die Tour. Startet sie wieder mit Tour starten auf der Einstellungsseite des Loot Guide oder mit /eui tour lootguide.",
	["Enter from level"] = "Zutritt ab Stufe",
	["Enter saves, Shift+Enter new line, Esc closes."] = "Eingabe speichert, Umschalt+Eingabe neue Zeile, Esc schließt.",
	["Enter saves, Shift+Enter starts a new line."] = "Eingabe speichert, Umschalt+Eingabe beginnt eine neue Zeile.",
	["Entered before the journal kept runs."] = "Betreten, bevor das Tagebuch Durchläufe aufzeichnete.",
	["Entrance"] = "Eingang",
	["Entrance %s."] = "Eingang %s.",
	["Entries"] = "Einträge",
	["Epic find"] = "Epischer Fund",
	["Epic finds and the wishlist items you got."] = "Epische Funde und die Wunschlisten-Gegenstände, die Ihr bekommen habt.",
	["Epic finds come from bosses deep in dungeons, later in your journey."] = "Epische Funde stammen von Bossen tief in Dungeons, später auf Eurer Reise.",
	["Epic finds come from bosses. These dungeons fit your level:"] = "Epische Funde stammen von Bossen. Diese Dungeons passen zu Eurer Stufe:",
	["Equip a ranged weapon first."] = "Legt zuerst eine Distanzwaffe an.",
	["Equipped %s"] = "%s angelegt",
	["Eras"] = "Epochen",
	["Essentials"] = "Das Wichtigste",
	["Estimates from fights against a target dummy with your own character sheet and public Classic combat rules. Set bonuses and item procs are not counted."] = "Schätzungen aus Kämpfen gegen eine Trainingspuppe mit Eurem eigenen Charakterbogen und öffentlichen Classic-Kampfregeln. Setboni und Gegenstandseffekte werden nicht gezählt.",
	["Everlook"] = "Everlook",
	["Every Loot Guide page is switched off. Turn pages on in /eui > Loot Guide."] = "Jede Seite des Loot Guide ist ausgeschaltet. Schaltet Seiten unter /eui > Loot Guide ein.",
	["Every PvP reward with its cost and the rank or standing it needs, plus a planner for the weeks to afford them."] = "Jede PvP-Belohnung mit Kosten und benötigtem Rang oder Ruf, dazu ein Planer für die Wochen, bis Ihr sie Euch leisten könnt.",
	["Every attunement and key step by step. Its next steps show up in Next trips and on Today."] = "Jede Einstimmung und jeder Schlüssel Schritt für Schritt. Die nächsten Schritte erscheinen in Nächste Reisen und bei Heute.",
	["Every attunement and key, step by step."] = "Jede Einstimmung und jeder Schlüssel, Schritt für Schritt.",
	["Every best-in-slot item is already yours or on your wishlist."] = "Jeder Best-in-Slot-Gegenstand gehört Euch bereits oder steht auf Eurer Wunschliste.",
	["Every craft per profession: what it makes, the skill it needs, the reagents you own and where the recipe comes from."] = "Jede Herstellung pro Beruf: was sie herstellt, die benötigte Fertigkeit, die Reagenzien, die Ihr besitzt, und woher das Rezept stammt.",
	["Every dungeon and raid run stays in your journal with who was in it. Its own code keeps them safe or moves them to another PC."] = "Jeder Dungeon- und Schlachtzugsdurchlauf bleibt in Eurem Tagebuch, samt allen, die dabei waren. Ein eigener Code hält sie sicher oder bringt sie auf einen anderen PC.",
	["Every dungeon and raid with its bosses, loot, drop chances and quests. Inside a dungeon the window opens on it."] = "Jeder Dungeon und Schlachtzug mit Bossen, Beute, Beutechancen und Quests. In einem Dungeon öffnet sich das Fenster bei ihm.",
	["Every dungeon and raid: bosses, drops with chances, quests and what is an upgrade for you."] = "Jeder Dungeon und Schlachtzug: Bosse, Beute mit Chancen, Quests und was eine Verbesserung für Euch ist.",
	["Every flight master you speak to adds a flight path. These zones fit your level:"] = "Jeder Flugmeister, mit dem Ihr sprecht, fügt eine Flugroute hinzu. Diese Zonen passen zu Eurer Stufe:",
	["Every idea for where to go next, with filters."] = "Jede Idee, wohin es als Nächstes geht, mit Filtern.",
	["Every idea, best first, with filters for dungeons, quests, attunements, and zones, for your group and the time you have. Hover a card to see every reason; Not now puts it away until your next level."] = "Jede Idee, die beste zuerst, mit Filtern für Dungeons, Quests, Einstimmungen und Zonen, für Eure Gruppe und Eure Zeit. Fahrt mit der Maus über eine Karte, um jeden Grund zu sehen; „Nicht jetzt“ legt sie bis zu Eurer nächsten Stufe weg.",
	["Every item, creature, quest and place in sortable tables with filters and a detail panel."] = "Jeder Gegenstand, jede Kreatur, Quest und jeder Ort in sortierbaren Tabellen mit Filtern und Detailbereich.",
	["Every item, mob, quest and vendor the loot data knows, with filters and sorting."] = "Jeder Gegenstand, Gegner, jede Quest und jeder Händler aus den Beutedaten, mit Filtern und Sortierung.",
	["Every keepsake, grouped by kind."] = "Jedes Andenken, nach Art gruppiert.",
	["Every kind of result."] = "Jede Art von Ergebnis.",
	["Every level is behind you"] = "Jede Stufe liegt hinter Euch",
	["Every level is behind you. The journal keeps writing down your runs, finds, and standings."] = "Jede Stufe liegt hinter Euch. Das Tagebuch notiert weiter Eure Durchläufe, Funde und Ruferfolge.",
	["Every login"] = "Bei jedem Login",
	["Every moment."] = "Jeder Moment.",
	["Every new standing"] = "Jeder neue Rang",
	["Every new standing, or Honored and up only. Changing it on a preset turns it into Custom."] = "Jeder neue Rang oder nur ab Wohlwollend. Eine Änderung an einer Vorgabe macht daraus Benutzerdefiniert.",
	["Every part and chapter of the Book. Click one to turn to it."] = "Jeder Teil und jedes Kapitel des Buchs. Klickt eines an, um dorthin zu blättern.",
	["Every quest you handed in since the journal began, with where, when, and what it gave."] = "Jede Quest, die Ihr seit Beginn des Tagebuchs abgegeben habt, mit Ort, Zeit und Belohnung.",
	["Every quest you handed in, with where, when, who gave it, and who came along; your quest log; and the quests the game remembers from before."] = "Jede abgegebene Quest mit Ort, Zeit, Auftraggeber und Begleitern; Euer Questlog; und die Quests, an die sich das Spiel von früher erinnert.",
	["Every run the Instances module recorded."] = "Jeder Durchlauf, den das Modul Instanzen aufgezeichnet hat.",
	["Every step for both sides and every class, also content the client does not list yet."] = "Jeder Schritt für beide Seiten und jede Klasse, auch Inhalte, die der Client noch nicht listet.",
	["Every suggestion, best first."] = "Jeder Vorschlag, der beste zuerst.",
	["Every time"] = "Jedes Mal",
	["Every way to get one item."] = "Jeder Weg zu einem Gegenstand.",
	["Every zone"] = "Jede Zone",
	["Every zone you visited, with its corners, time, kills, and quests, and every dungeon with its runs."] = "Jede besuchte Zone mit ihren Winkeln, Zeit, Siegen und Quests, und jeder Dungeon mit seinen Durchläufen.",
	["Every zone's quests in the Loot Guide's Catalog: how many you have done, what is left and who gives them."] = "Die Quests jeder Zone im Katalog des Loot Guide: wie viele Ihr erledigt habt, was noch fehlt und wer sie vergibt.",
	["Every zone's quests: how many you have done, what is left and who gives it, with a Map button for each giver."] = "Die Quests jedes Gebiets: wie viele Ihr erledigt habt, was noch offen ist und wer sie vergibt, mit einem Karte-Knopf für jeden Questgeber.",
	["Everyone falls sometime. There is no need to chase this one."] = "Jeder fällt irgendwann. Diesem hier müsst Ihr nicht nachjagen.",
	["Everyone falls sometime. There is no need to chase this one; here is what fits you instead:"] = "Jeder fällt irgendwann. Diesem hier müsst Ihr nicht nachjagen; das hier passt stattdessen zu Euch:",
	["Everyone passed"] = "Alle passen",
	["Everyone you grouped with."] = "Alle, mit denen Ihr in einer Gruppe wart.",
	["Everything is selected. Press Ctrl+C and share it. It holds your gear plans, spec and talents, not your name or realm."] = "Alles ist markiert. Drückt Strg+C und teilt es. Es enthält Eure Ausrüstungspläne, Spezialisierung und Talente, nicht Euren Namen oder Realm.",
	["Everything is selected. Press Ctrl+C and share it. Others paste it into /eui import or the wishlist's Import."] = "Alles ist markiert. Drückt Strg+C und teilt es. Andere fügen es in /eui import oder beim Import der Wunschliste ein.",
	["Everything reached. Start a new one with New goal."] = "Alles erreicht. Beginnt ein neues mit Neues Ziel.",
	["Everything you can get at your level is already as good as what you wear."] = "Alles, was Ihr auf Eurer Stufe bekommen könnt, ist schon so gut wie das, was Ihr tragt.",
	["Everything, rare (blue) finds too, long chapters, every chapter open and a taller tracker."] = "Alles, auch seltene (blaue) Funde, lange Kapitel, jedes Kapitel offen und ein höherer Tracker.",
	["Excavation Site"] = "Ausgrabungsstätte",
	["Exclamation mark"] = "Ausrufezeichen",
	["Experience and money next to each quest you handed in."] = "Erfahrung und Geld neben jeder abgegebenen Quest.",
	["Explored %s"] = "%s erkundet",
	["Export (share string)"] = "Exportieren (Text zum Teilen)",
	["Export a printable page"] = "Eine druckbare Seite exportieren",
	["Export as Markdown"] = "Als Markdown exportieren",
	["Export as plain text"] = "Als reinen Text exportieren",
	["Export formats: %s."] = "Exportformate: %s.",
	["Factions that count you as Honored or better."] = "Fraktionen, bei denen Ihr wohlwollend oder besser steht.",
	["Fanfare's \"Journal moment\" triggers play or show with each moment. While such a trigger, or a level-up or boss-kill trigger, has a sound, the moment plays none of its own, so you hear one sound."] = "Die Auslöser \"Tagebuchmoment\" von Fanfare spielen oder zeigen etwas bei jedem Moment. Solange ein solcher Auslöser oder ein Auslöser für Stufenaufstieg oder Bosssieg einen Klang hat, spielt der Moment keinen eigenen, damit Ihr nur einen Klang hört.",
	["Farmed for %s"] = "%s gefarmt",
	["Fast (8 ms a frame)"] = "Schnell (8 ms pro Frame)",
	["Feet"] = "Füße",
	["Fellowship"] = "Gemeinschaft",
	["Fewer"] = "Weniger",
	["Fiery Weapon"] = "Feurige Waffe",
	["Fighting"] = "Kämpfen",
	["Fights against a target dummy with the best items of your list (one-minute fights, out of combat). Progress shows here, in the datatext and as a toast when done."] = "Kämpfe gegen eine Trainingspuppe mit den besten Gegenständen Eurer Liste (einminütige Kämpfe, außerhalb des Kampfes). Der Fortschritt erscheint hier, im Datentext und als Toast, wenn er fertig ist.",
	["Fights against a target dummy with the best items of your list per slot: a quick pass, exact runs of the top picks, then the best set (one-minute fights, out of combat)."] = "Kämpfe gegen eine Trainingspuppe mit den besten Gegenständen Eurer Liste pro Platz: ein schneller Durchgang, genaue Läufe der besten Kandidaten, dann das beste Set (einminütige Kämpfe, außerhalb des Kampfes).",
	["Fights against a target dummy with this item instead of what you wear in its slot (about a second, out of combat). The result shows here, in the tooltip and as a toast."] = "Kämpfe gegen eine Trainingspuppe mit diesem Gegenstand statt dem, den Ihr in seinem Platz tragt (etwa eine Sekunde, außerhalb des Kampfes). Das Ergebnis erscheint hier, im Tooltip und als Toast.",
	["Fights against a target dummy with your own character sheet. Slower, but counts how your talents and spells use each stat. Items not simulated yet keep the weights gain."] = "Kämpfe gegen eine Trainingspuppe mit Eurem eigenen Charakterbogen. Langsamer, aber zählt, wie Eure Talente und Zauber jeden Wert nutzen. Noch nicht simulierte Gegenstände behalten den Gewinn nach Gewichtung.",
	["Fights against a target dummy with your own character sheet: DPS numbers for your gear, Best in Slot and plan sets. /eui sim opens its window."] = "Kämpfe gegen eine Trainingspuppe mit Eurem eigenen Charakterbogen: DPS-Werte für Eure Ausrüstung, Best in Slot und Plansets. /eui sim öffnet sein Fenster.",
	["Fills an empty slot"] = "Füllt einen leeren Platz",
	["Fills the set with the Best in Slot items (the simulated set in Simulator mode)."] = "Füllt das Set mit den Best-in-Slot-Gegenständen (im Simulatormodus mit dem simulierten Set).",
	["Fills the set with your equipped gear."] = "Füllt das Set mit Eurer angelegten Ausrüstung.",
	["Filter"] = "Filter",
	["Filter: %s · %s"] = "Filter: %s · %s",
	["Filter: pick your spec, the armor you wear and where your gear may come from. Every page and tooltip uses the same list."] = "Filter: Wählt Eure Spezialisierung, die Rüstung, die Ihr tragt, und woher Eure Ausrüstung stammen darf. Jede Seite und jeder Tooltip nutzt dieselbe Liste.",
	["Filters for dungeons, quests, attunements, and zones."] = "Filter für Dungeons, Quests, Einstimmungen und Zonen.",
	["Filters the crafts by the name of what they make."] = "Filtert die Herstellungen nach dem Namen dessen, was sie herstellen.",
	["Filters the rewards and quests by name."] = "Filtert Belohnungen und Quests nach Namen.",
	["Filters the rewards by name."] = "Filtert die Belohnungen nach Namen.",
	["Filters the rows by item name and source."] = "Filtert die Zeilen nach Gegenstandsname und Quelle.",
	["Find a group"] = "Eine Gruppe finden",
	["Finds"] = "Funde",
	["Finds events by name."] = "Findet Ereignisse nach Namen.",
	["Finds from"] = "Funde aus",
	["Finds sets and tokens by their name or a piece's name."] = "Findet Sets und Marken nach ihrem Namen oder dem Namen eines Teils.",
	["Finds, mounts, and companions."] = "Funde, Reittiere und Gefährten.",
	["Finger"] = "Finger",
	["Finish %s"] = "%s abschließen",
	["Finish %s."] = "Schließt %s ab.",
	["Finish a quest"] = "Eine Quest abschließen",
	["Finish an attunement"] = "Eine Einstimmung abschließen",
	["Finished the chain with %s"] = "Die Reihe mit %s abgeschlossen",
	["Fireball"] = "Feuerball",
	["First %s."] = "Erstmals %s.",
	["First Aid"] = "Erste Hilfe",
	["First beaten %s · %d kills"] = { one = "Zuerst besiegt %s · %d Sieg", other = "Zuerst besiegt %s · %d Siege" },
	["First boss kills, epic finds, Honored and up, new mounts, mastered professions and attunements get their own card. Off: they are plain rows."] = "Erste Bosssiege, epische Funde, ab Wohlwollend, neue Reittiere, gemeisterte Berufe und Einstimmungen bekommen eine eigene Karte. Aus: Sie sind einfache Zeilen.",
	["First came here"] = "Zuerst hier gewesen",
	["First came here %s"] = "Zuerst hier gewesen %s",
	["First came here %s at level %s."] = "Zuerst hier gewesen %s auf Stufe %s.",
	["First came here %s, level %d"] = "Zuerst hier gewesen %s, Stufe %d",
	["First came here %s."] = "Zuerst hier gewesen %s.",
	["First dungeon sound"] = "Ton für ersten Dungeon",
	["First dungeons"] = "Erste Dungeons",
	["First kill"] = "Erster Sieg",
	["First kill · killed %d times since"] = { one = "Erster Sieg · seitdem %d Mal besiegt", other = "Erster Sieg · seitdem %d Mal besiegt" },
	["First kills, epic finds, Honored standings, mounts, and attunements become keepsakes. Right-click any moment in the Journey to keep it."] = "Erste Siege, epische Funde, wohlwollende Ruferfolge, Reittiere und Einstimmungen werden zu Andenken. Rechtsklickt einen Moment in der Reise, um ihn zu behalten.",
	["First kills, one card per run."] = "Erste Siege, eine Karte pro Durchlauf.",
	["First time in %s"] = "Zum ersten Mal in %s",
	["First visit"] = "Erster Besuch",
	["First visit to %s"] = "Erster Besuch in %s",
	["First visit, level %d"] = "Erster Besuch, Stufe %d",
	["First: %s"] = "Zuerst: %s",
	["Firsts"] = "Erste Male",
	["Fit"] = "Passend",
	["Fits your level (%d; the dungeon is %d-%d)."] = "Passt zu Eurer Stufe (%d; der Dungeon ist %d-%d).",
	["Fits your level (%d; the zone is %d-%d)."] = "Passt zu Eurer Stufe (%d; die Zone ist %d-%d).",
	["Fits your level (quest level %d)."] = "Passt zu Eurer Stufe (Queststufe %d).",
	["Fits your time: about %d minutes."] = { one = "Passt zu Eurer Zeit: etwa %d Minute.", other = "Passt zu Eurer Zeit: etwa %d Minuten." },
	["Five-player dungeons and their wings."] = "Dungeons für fünf Spieler und ihre Flügel.",
	["Flametongue"] = "Flammenzunge",
	["Fleeting company"] = "Flüchtige Bekanntschaften",
	["Flight path: %s"] = "Flugroute: %s",
	["Flight paths"] = "Flugrouten",
	["Flight paths you learned while the journal was kept."] = "Flugrouten, die Ihr gelernt habt, während das Tagebuch geführt wurde.",
	["Floor"] = "Ebene",
	["Floor %d"] = "Ebene %d",
	["Floors: each button shows one floor. The map remembers the one you picked last."] = "Ebenen: Jeder Knopf zeigt eine Ebene. Die Karte merkt sich die zuletzt gewählte.",
	["Flowchart"] = "Flussdiagramm",
	["Flowchart, your faction, toasts on, a line in the Journal."] = "Flussdiagramm, Eure Fraktion, Toasts an, eine Zeile im Tagebuch.",
	["Fold older chapters"] = "Ältere Kapitel einklappen",
	["Follow General > Animations"] = "Wie Allgemein > Animationen",
	["For %s"] = "Für %s",
	["For You"] = "Für Euch",
	["For You also counts raids when it picks the best instance and the next upgrades."] = "Für Euch zählt auch Schlachtzüge, wenn es die beste Instanz und die nächsten Verbesserungen wählt.",
	["For You first, dungeons and quests near your level, no raids; Classic drop chances only."] = "Für Euch zuerst, Dungeons und Quests nahe Eurer Stufe, keine Schlachtzüge; nur Classic-Beutechancen.",
	["For this character: your stat weights (fast, the same as the Upgrades arrows), or the simulator (DPS against a target dummy, run when you press Sim)."] = "Für diesen Charakter: Eure Wertgewichte (schnell, dieselben wie die Verbesserungspfeile) oder der Simulator (DPS gegen eine Trainingsattrappe, läuft, wenn Ihr Sim drückt).",
	["For you"] = "Für Euch",
	["For your level"] = "Für Eure Stufe",
	["Forever"] = "Forever",
	["Forever Journal"] = "Forever Journal",
	["Forever Journal imported"] = "Forever Journal importiert",
	["Forever Journal is loaded"] = "Forever Journal ist geladen",
	["Forever dungeon"] = "Forever-Dungeon",
	["Forever dungeons"] = "Forever-Dungeons",
	["Forever overlay %s, %d entries"] = { one = "Forever-Überlagerung %s, %d Eintrag", other = "Forever-Überlagerung %s, %d Einträge" },
	["Forever quests"] = "Forever-Quests",
	["Forever quests seen"] = "Gesehene Forever-Quests",
	["Forever quests you accept are remembered on this PC."] = "Forever-Quests, die Ihr annehmt, werden auf diesem PC gespeichert.",
	["Forget this name?"] = "Diesen Namen vergessen?",
	["Forward"] = "Vorwärts",
	["Found %s"] = "Gefunden: %s",
	["Found %s in %s"] = "Gefunden: %s in %s",
	["Four tables: items, creatures, quests and places. Each keeps its own search and filters until you log out."] = "Vier Tabellen: Gegenstände, Kreaturen, Quests und Orte. Jede behält ihre Suche und Filter, bis Ihr Euch ausloggt.",
	["From %s, %s"] = "Von %s, %s",
	["From Best in Slot"] = "Aus Best in Slot",
	["From Zone Info."] = "Aus Zone Info.",
	["From kills, quests, and exploring."] = "Aus Siegen, Quests und Erkundung.",
	["From level %d"] = "Ab Stufe %d",
	["From loot, quests, and sales."] = "Aus Beute, Quests und Verkäufen.",
	["From now on, levels, places, first kills, and finds are written down as they happen."] = "Ab jetzt werden Stufen, Orte, erste Siege und Funde notiert, sobald sie passieren.",
	["From now on, runs, first kills, finds, and standings are written down as they happen."] = "Ab jetzt werden Durchläufe, erste Siege, Funde und Ruferfolge notiert, sobald sie passieren.",
	["From the game's dungeon finder."] = "Aus dem Dungeonbrowser des Spiels.",
	["From the game's kill statistic and its experience lines, at each level."] = "Aus der Siegstatistik des Spiels und seinen Erfahrungszeilen, auf jeder Stufe.",
	["From the game's list of completed quests (the Characters record). Undated: the game does not say when you did them."] = "Aus der Liste abgeschlossener Quests des Spiels (der Charaktereintrag). Ohne Datum: Das Spiel sagt nicht, wann Ihr sie erledigt habt.",
	["From the game."] = "Aus dem Spiel.",
	["From what I wear"] = "Ausgehend von meiner Ausrüstung",
	["From wishlist"] = "Von der Wunschliste",
	["Frostbolt"] = "Frostblitz",
	["Frostbrand"] = "Frostbrand",
	["Frostwolf Clan"] = "Frostwolfklan",
