	["Go and explore. Look for the people with a yellow mark over their heads near where you started: they have your first quests."] = "Zieht los und erkundet. Sucht in der Nähe Eures Startpunkts nach Leuten mit einer gelben Markierung über dem Kopf: Sie haben Eure ersten Quests.",
