	["Hidden from the page until you restore them. Delete removes them for good."] = "Von der Seite ausgeblendet, bis Ihr sie wiederherstellt. Löschen entfernt sie endgültig.",
	["Hidden from the page until you restore them. Delete removes them for good. Pinned notes stay on your Journey until deleted."] = "Von der Seite ausgeblendet, bis Ihr sie wiederherstellt. Löschen entfernt sie endgültig. Angeheftete Notizen bleiben bis zum Löschen in Eurer Reise.",
	["Hide done"] = "Erledigte ausblenden",
