	["Hides items your class cannot use (armor kind, weapon, class)."] = "Blendet Gegenstände aus, die Eure Klasse nicht nutzen kann (Rüstungsart, Waffe, Klasse).",
	["Hides results your class cannot use."] = "Blendet Ergebnisse aus, die Eure Klasse nicht nutzen kann.",
	["Hides rewards your class cannot use."] = "Blendet Belohnungen aus, die Eure Klasse nicht nutzen kann.",
	["Hides the step details."] = "Blendet die Schrittdetails aus.",
	["Hides this goal from the page. The archive keeps it."] = "Blendet dieses Ziel auf der Seite aus. Das Archiv behält es.",
	["Hides this note from the page. The archive keeps it, and a pinned note stays on your Journey."] = "Blendet diese Notiz auf der Seite aus. Das Archiv behält sie, und eine angeheftete Notiz bleibt in Eurer Reise.",
	["Hides this quest from the page. The archive keeps it."] = "Blendet diese Quest auf der Seite aus. Das Archiv behält sie.",
	["Hides wished items you already beat with gear you own."] = "Blendet gewünschte Gegenstände aus, die Eure eigene Ausrüstung schon übertrifft.",
	["Higher levels"] = "Höhere Stufen",
	["Hints show here: where the markers come from and what the map can't know (there is no live position inside dungeons)."] = "Hier erscheinen Hinweise: woher die Markierungen kommen und was die Karte nicht wissen kann (in Dungeons gibt es keine Live-Position).",
	["Hit chance"] = "Trefferchance",
	["Hit chance (1 %)"] = "Trefferchance (1 %)",
	["Honor and mark costs show once you have visited the vendor; nothing is estimated."] = "Ehren- und Abzeichenkosten erscheinen, sobald Ihr den Händler besucht habt; nichts wird geschätzt.",
	["Honored and up only"] = "Nur ab Wohlwollend",
	["Hover a card to see why it ranks where it does."] = "Fahrt mit der Maus über eine Karte, um zu sehen, warum sie dort eingeordnet ist.",
	["Hover them once (the game then sends their stats) or install EldoUI_LootData."] = "Fahrt einmal mit der Maus darüber (das Spiel schickt dann ihre Werte) oder installiert EldoUI_LootData.",
	["How a chain shows: a flowchart of steps, or one step per row (easier to read at a small window scale)."] = "Wie eine Reihe angezeigt wird: als Flussdiagramm der Schritte oder ein Schritt pro Zeile (bei kleiner Fensterskalierung leichter zu lesen).",
	["How long ago they sent it."] = "Wie lange es her ist, dass sie es geschickt haben.",
	["How long each fight lasts for the Character and Sets tabs. Best in Slot runs always use one-minute fights."] = "Wie lange jeder Kampf für die Reiter Charakter und Sets dauert. Best-in-Slot-Läufe nutzen immer einminütige Kämpfe.",
	["How many goals the tracker lists."] = "Wie viele Ziele der Tracker auflistet.",
	["How many guild members a step's tooltip lists by name."] = "Wie viele Gildenmitglieder der Tooltip eines Schritts mit Namen auflistet.",
	["How many of its drops are upgrades for you."] = "Wie viele seiner Beutestücke Verbesserungen für Euch sind.",
	["How many runs?"] = "Wie viele Durchläufe?",
	["How many waiting reminders the tracker lists."] = "Wie viele wartende Erinnerungen der Tracker auflistet.",
	["How many?"] = "Wie viele?",
	["How much experience?"] = "Wie viel Erfahrung?",
	["How much gold?"] = "Wie viel Gold?",
	["How much of each frame the simulator may use. Turbo finishes sooner but can lower your frame rate while it runs."] = "Wie viel von jedem Frame der Simulator nutzen darf. Turbo ist schneller fertig, kann aber Eure Bildrate senken, solange er läuft.",
	["How much story"] = "Wie viel Geschichte",
	["How much the journal shows"] = "Wie viel das Tagebuch zeigt",
	["How tall each row in the Loot Guide lists is. Compact fits more on a page."] = "Wie hoch jede Zeile in den Listen des Loot Guide ist. Kompakt passt mehr auf eine Seite.",
	["How the Quests page groups the quests you handed in: by day, level, zone or type."] = "Wie die Seite Quests Eure abgegebenen Quests gruppiert: nach Tag, Stufe, Zone oder Art.",
	["How the giver pins look: the quest icon, colored dots, bright color-blind safe colors, the bronze of the Forever art style, or small plain dots."] = "Wie die Markierungen der Questgeber aussehen: das Questsymbol, farbige Punkte, helle farbenblind-sichere Farben, die Bronze des Forever-Kunststils oder kleine schlichte Punkte.",
	["How the rows are ordered. A click on a column header sorts too."] = "Wie die Zeilen sortiert sind. Ein Klick auf eine Spaltenüberschrift sortiert ebenfalls.",
	["How the story is told: Chronicle (a careful record), Bard (warm and heroic) or Ledger (facts only, short rows). The facts are the same in every tone."] = "Wie die Geschichte erzählt wird: Chronik (eine sorgfältige Aufzeichnung), Barde (warm und heldenhaft) oder Kassenbuch (nur Fakten, kurze Zeilen). Die Fakten sind in jedem Tonfall dieselben.",
