	["Levels, deaths, notes, goals and keepsakes only. Short chapters, a small tracker and moments for levels, first dungeons, goals and keepsakes."] = "Nur Stufen, Tode, Notizen, Ziele und Andenken. Kurze Kapitel, ein kleiner Tracker und Momente für Stufen, erste Dungeons, Ziele und Andenken.",
