	["Lines past this height fold into +n more."] = "Zeilen über diese Höhe hinaus klappen zu +n weitere zusammen.",
	["Link in chat"] = "Im Chat verlinken",
	["List only quests for your side, race, class and professions. Off also shows the others, in a Not for you group."] = "Nur Quests für Eure Seite, Euer Volk, Eure Klasse und Eure Berufe auflisten. Aus zeigt auch die anderen, in einer Gruppe Nichts für Euch.",
	["Lists only what you have not learned or do not own yet."] = "Listet nur, was Ihr noch nicht erlernt habt oder noch nicht besitzt.",
	["Lists the factions you have not met too (Loot Guide options: Reputation: factions you have not met)."] = "Listet auch die Fraktionen, denen Ihr noch nicht begegnet seid (Loot-Guide-Optionen: Ruf: Fraktionen, denen Ihr noch nicht begegnet seid).",
	["Load the journal of %s (level %s, saved %s by %s) into this character?"] = "Das Tagebuch von %s (Stufe %s, gespeichert %s von %s) in diesen Charakter laden?",
	["Load the runs of %s (saved %s) into this character?"] = "Die Durchläufe von %s (gespeichert %s) in diesen Charakter laden?",
	["Loads a code from EldoUI (!EUJ1!) or Forever Journal (FJ1:). You see what it holds, then Merge or Replace."] = "Lädt einen Code aus EldoUI (!EUJ1!) oder Forever Journal (FJ1:). Ihr seht, was er enthält, dann Zusammenführen oder Ersetzen.",
	["Loads a runs code (!EUJR1!). You see what it holds, then Merge or Replace."] = "Lädt einen Durchlaufcode (!EUJR1!). Ihr seht, was er enthält, dann Zusammenführen oder Ersetzen.",
	["Log out in an inn or a city to rest faster."] = "Loggt Euch in einem Gasthaus oder einer Stadt aus, um schneller zu erholen.",
	["Long"] = "Lang",
	["Longest: level %d (%s)"] = "Am längsten: Stufe %d (%s)",
	["Look for the people with a yellow mark over their heads near where you started: they have your first quests. Ideas show here as soon as there is one."] = "Sucht in der Nähe Eures Startpunkts nach Leuten mit einer gelben Markierung über dem Kopf: Sie haben Eure ersten Quests. Ideen erscheinen hier, sobald es eine gibt.",
