	["Merge"] = "Zusammenführen",
	["Merge adds everything in the backup that your journal is missing, and keeps everything since. Replace puts the journal back exactly as it was then."] = "Zusammenführen fügt alles aus der Sicherung hinzu, was Eurem Tagebuch fehlt, und behält alles danach. Ersetzen stellt das Tagebuch genau so wieder her, wie es damals war.",
	["Merge adds the runs your journal is missing and never adds one twice. Replace puts your runs back exactly as they were then."] = "Zusammenführen fügt die Durchläufe hinzu, die Eurem Tagebuch fehlen, und fügt keinen doppelt hinzu. Ersetzen stellt Eure Durchläufe genau so wieder her, wie sie damals waren.",
	["Merge combines it with your journal: nothing from either is lost. Replace uses only the pasted one."] = "Zusammenführen kombiniert es mit Eurem Tagebuch: Von keinem geht etwas verloren. Ersetzen nutzt nur das eingefügte.",
