	["None braved yet. Each dungeon gets a card of its own, with runs and time inside."] = "Noch keiner gewagt. Jeder Dungeon bekommt eine eigene Karte mit Durchläufen und Zeit darin.",
	["None of these quests is in your quest log."] = "Keine dieser Quests ist in Eurem Questlog.",
	["None yet."] = "Noch keine.",
	["None yet. A quest counts once you both have it and one of its objectives moves forward while you are grouped."] = "Noch keine. Eine Quest zählt, sobald Ihr sie beide habt und eines ihrer Ziele vorankommt, während Ihr gruppiert seid.",
	["Not an upgrade now"] = "Derzeit keine Verbesserung",
	["Not done"] = "Nicht erledigt",
	["Not equipment"] = "Keine Ausrüstung",
	["Not for you"] = "Nichts für Euch",
	["Not for you: %s"] = "Nichts für Euch: %s",
	["Not for your side, race, class or profession."] = "Nicht für Eure Seite, Euer Volk, Eure Klasse oder Euren Beruf.",
	["Not gear"] = "Keine Ausrüstung",
	["Not in WoW: Forever yet"] = "Noch nicht in WoW: Forever",
	["Not known"] = "Nicht bekannt",
	["Not learned only"] = "Nur nicht erlernte",
	["Not out yet: opens %s"] = "Noch nicht verfügbar: öffnet %s",
	["Not rated yet"] = "Noch nicht bewertet",
	["Not recorded"] = "Nicht aufgezeichnet",
	["Not recorded: the level log was off."] = "Nicht aufgezeichnet: Das Stufenprotokoll war aus.",
	["Not tracked: marked done when the next step is done"] = "Nicht verfolgt: als erledigt markiert, wenn der nächste Schritt erledigt ist",
	["Not visited yet"] = "Noch nicht besucht",
	["Not yet"] = "Noch nicht",
	["Not yet explored"] = "Noch nicht erkundet",
	["Not yet."] = "Noch nicht.",
	["Note deleted."] = "Notiz gelöscht.",
	["Note for %s (up to %d letters, shown in its tooltip; empty removes it):"] = "Notiz für %s (bis zu %d Zeichen, im Tooltip gezeigt; leer entfernt sie):",
	["Note saved sound"] = "Ton für gespeicherte Notiz",
	["Note saved."] = "Notiz gespeichert.",
	["Noted"] = "Notiert",
	["Noted in your journal."] = "In Eurem Tagebuch notiert.",
	["Noted. Reminder set: %s."] = "Notiert. Erinnerung gesetzt: %s.",
	["Notes and goals"] = "Notizen und Ziele",
	["Notes on the world map"] = "Notizen auf der Weltkarte",
	["Notes remember where and when you wrote them. Press Enter in the box above to save one."] = "Notizen merken sich, wo und wann Ihr sie geschrieben habt. Drückt im Feld oben die Eingabetaste, um eine zu speichern.",
	["Notes saved"] = "Gespeicherte Notizen",
	["Notes show as pins on the world map and minimap where you wrote them, with the Map Notes switch. Needs the Map Notes module."] = "Notizen erscheinen als Markierungen auf der Weltkarte und der Minikarte dort, wo Ihr sie geschrieben habt, mit dem Schalter Kartennotizen. Benötigt das Modul Kartennotizen.",
	["Notes that remember where and when you wrote them, and reminders that show when you get somewhere."] = "Notizen, die sich merken, wo und wann Ihr sie geschrieben habt, und Erinnerungen, die erscheinen, wenn Ihr irgendwo ankommt.",
	["Notes the quests, dungeons and zone level ranges the game shows you that the quest data does not know yet, so the quest pages can show them. Only what dialogs and the map show is read."] = "Notiert die Quests, Dungeons und Stufenbereiche von Zonen, die das Spiel Euch zeigt und die die Questdaten noch nicht kennen, damit die Questseiten sie zeigen können. Gelesen wird nur, was Dialoge und die Karte zeigen.",
	["Notes written here"] = "Hier geschriebene Notizen",
	["Notes you archive wait here until you restore or delete them."] = "Archivierte Notizen warten hier, bis Ihr sie wiederherstellt oder löscht.",
	["Notes you archived. Restore or delete them there."] = "Notizen, die Ihr archiviert habt. Stellt sie dort wieder her oder löscht sie.",
	["Nothing fits: turn on Higher levels, or install EldoUI_LootData for the full item list."] = "Nichts passt: Schaltet Höhere Stufen ein oder installiert EldoUI_LootData für die vollständige Gegenstandsliste.",
	["Nothing fits: widen the filter or turn on Higher levels."] = "Nichts passt: Erweitert den Filter oder schaltet Höhere Stufen ein.",
	["Nothing found"] = "Nichts gefunden",
	["Nothing here fits your level."] = "Nichts hier passt zu Eurer Stufe.",
	["Nothing here is an upgrade for you now."] = "Nichts hier ist derzeit eine Verbesserung für Euch.",
	["Nothing in progress."] = "Nichts in Arbeit.",
	["Nothing in the Loot Guide matches %q."] = "Nichts im Loot Guide passt zu %q.",
	["Nothing in this group."] = "Nichts in dieser Gruppe.",
	["Nothing is lost: it merges with what My Adventure has, a backup is taken first, and Undo puts it back. Forever Journal's own data is only read, never changed."] = "Nichts geht verloren: Es wird mit dem zusammengeführt, was Mein Abenteuer hat, vorher wird eine Sicherung angelegt, und Rückgängig stellt es wieder her. Die eigenen Daten von Forever Journal werden nur gelesen, nie geändert.",
	["Nothing is waiting"] = "Nichts wartet",
	["Nothing matches"] = "Nichts passt",
	["Nothing matches the filters."] = "Nichts passt zu den Filtern.",
	["Nothing new to report yet. The Journal notes the quests, dungeons, and zones the data does not know as you meet them."] = "Noch nichts Neues zu melden. Das Tagebuch notiert die Quests, Dungeons und Zonen, die die Daten nicht kennen, sobald Ihr ihnen begegnet.",
	["Nothing of this kind right now"] = "Gerade nichts dieser Art",
	["Nothing on your list: widen the filter"] = "Nichts auf Eurer Liste: Erweitert den Filter",
	["Nothing picked"] = "Nichts gewählt",
	["Nothing put away"] = "Nichts weggelegt",
	["Nothing to read. Paste a journal code first."] = "Nichts zu lesen. Fügt zuerst einen Tagebuch-Code ein.",
	["Nothing to read. Paste a runs code first."] = "Nichts zu lesen. Fügt zuerst einen Durchlaufcode ein.",
	["Nothing to show yet"] = "Noch nichts anzuzeigen",
	["Nothing to suggest right now"] = "Gerade nichts vorzuschlagen",
	["Nothing to suggest yet"] = "Noch nichts vorzuschlagen",
	["Nothing to work towards yet"] = "Noch nichts, worauf Ihr hinarbeitet",
	["Nothing to work towards yet. Start one with New goal."] = "Noch nichts, worauf Ihr hinarbeitet. Beginnt eines mit Neues Ziel.",
	["Nothing worn"] = "Nichts angelegt",
	["Nothing worn in that slot"] = "In diesem Platz ist nichts angelegt",
	["Nothing written down yet"] = "Noch nichts aufgeschrieben",
	["Nothing you own matches %q. Turn off Owned to search everything."] = "Nichts in Eurem Besitz passt zu %q. Schaltet Im Besitz aus, um alles zu durchsuchen.",
	["Now: %s."] = "Jetzt: %s.",
	["Nowhere yet"] = "Noch nirgends",
	["Nowhere yet. The road is waiting."] = "Noch nirgends. Der Weg wartet.",
	["Numbered boss markers from the loot data on the dungeon map window. They never show where you are."] = "Nummerierte Bossmarkierungen aus den Beutedaten im Fenster der Dungeonkarte. Sie zeigen nie, wo Ihr seid.",
	["Numbered markers are the bosses, from the Classic data. Click one for its loot; click it again to close the list."] = "Nummerierte Markierungen sind die Bosse, aus den Classic-Daten. Klickt eine für ihre Beute an; klickt erneut, um die Liste zu schließen.",
	["Object"] = "Objekt",
	["Object %d"] = "Objekt %d",
	["Objectives"] = "Questziele",
	["Off-hand swings"] = "Schläge mit der Schildhand",
	["On a character that gives, takes or is the target of an attunement step: which step and how far you are. Nothing shows when the game hides who it is."] = "Bei einem Charakter, der einen Einstimmungsschritt vergibt, annimmt oder dessen Ziel ist: welcher Schritt und wie weit Ihr seid. Nichts erscheint, wenn das Spiel verbirgt, wer es ist.",
	["On a creature that can drop an item that starts a quest: the item, the quest and the drop chance, until you have the item or did the quest."] = "Bei einer Kreatur, die einen Gegenstand fallen lassen kann, der eine Quest beginnt: der Gegenstand, die Quest und die Beutechance, bis Ihr den Gegenstand habt oder die Quest erledigt ist.",
	["On a level-up the moment links to the dungeons, quests, spells and attunement steps that just opened."] = "Bei einem Stufenaufstieg verlinkt der Moment die Dungeons, Quests, Zauber und Einstimmungsschritte, die sich gerade geöffnet haben.",
	["On a quest link: when you took it or handed it in, at what level and where, and whether it is part of your next trip."] = "Bei einem Questlink: wann Ihr sie angenommen oder abgegeben habt, auf welcher Stufe und wo, und ob sie Teil Eurer nächsten Reise ist.",
	["On an item that is a step of an attunement: which one, whether you have it, and with Shift the next step."] = "Bei einem Gegenstand, der Schritt einer Einstimmung ist: welche, ob Ihr ihn habt und mit Umschalt den nächsten Schritt.",
	["On an item:"] = "Bei einem Gegenstand:",
	["On an item: when and where your journal saw you find it or put it on, and at what level."] = "Bei einem Gegenstand: wann und wo Euer Tagebuch gesehen hat, dass Ihr ihn gefunden oder angelegt habt, und auf welcher Stufe.",
	["On the way"] = "Unterwegs",
	["On your objective tracker."] = "In Eurer Zielverfolgung.",
	["On your own"] = "Allein",
	["On your wishlist"] = "Auf Eurer Wunschliste",
	["On your wishlist %s"] = "Auf Eurer Wunschliste %s",
	["On your wishlist."] = "Auf Eurer Wunschliste.",
	["Once a day"] = "Einmal am Tag",
	["Once a week"] = "Einmal pro Woche",
	["Once you come here, this page fills with what happened."] = "Sobald Ihr hierherkommt, füllt sich diese Seite mit dem, was geschah.",
	["One group of rewards, or all of them."] = "Eine Belohnungsgruppe oder alle.",
	["One group per day you played."] = "Eine Gruppe pro gespieltem Tag.",
	["One group per day, newest first."] = "Eine Gruppe pro Tag, neueste zuerst.",
	["One group per level, highest first."] = "Eine Gruppe pro Stufe, höchste zuerst.",
	["One group per zone, the latest first."] = "Eine Gruppe pro Zone, die letzte zuerst.",
	["One group per zone."] = "Eine Gruppe pro Zone.",
	["One kind of set, or all."] = "Eine Art von Set oder alle.",
	["One kind, like Mottled Worg. Counts each one that gives you experience."] = "Eine einzelne Kreaturenart, mit dem Namen aus dem Spiel. Zählt jede, die Euch Erfahrung bringt.",
	["One line for the tooltip."] = "Eine Zeile für den Tooltip.",
	["One line with the next thing that matters: a ready hand-in, trip prep or the next attunement step."] = "Eine Zeile mit dem Nächsten, was zählt: eine fertige Abgabe, Reisevorbereitung oder der nächste Einstimmungsschritt.",
	["One list, the most likely drop first."] = "Eine Liste, die wahrscheinlichste Beute zuerst.",
	["One more point is worth"] = "Ein Punkt mehr ist wert",
	["One of these is enough"] = "Eins davon genügt",
	["One of your professions."] = "Einer Eurer Berufe.",
	["One particular dungeon, once or many times."] = "Ein bestimmter Dungeon, einmal oder viele Male.",
	["One quest, or the last quest of a chain you are working on."] = "Eine Quest oder die letzte Quest einer Reihe, an der Ihr arbeitet.",
	["One step per row and finished attunements hidden: easy to read at a small window scale."] = "Ein Schritt pro Zeile und abgeschlossene Einstimmungen ausgeblendet: gut lesbar bei kleiner Fensterskalierung.",
	["One step per row, in order. Easier to read at a small window scale."] = "Ein Schritt pro Zeile, der Reihe nach. Besser lesbar bei kleiner Fensterskalierung.",
	["One summary when you leave"] = "Eine Zusammenfassung beim Verlassen",
	["One-hand"] = "Einhändig",
	["Only %s"] = "Nur %s",
	["Only %s."] = "Nur %s.",
	["Only by hand"] = "Nur von Hand",
	["Only crafts learned in this skill range."] = "Nur Rezepte, die in diesem Fertigkeitsbereich erlernt werden.",
	["Only creatures that drop at least one upgrade for you."] = "Nur Kreaturen, die mindestens eine Verbesserung für Euch fallen lassen.",
	["Only dungeons and raids."] = "Nur Dungeons und Schlachtzüge.",
	["Only guild members who are online now."] = "Nur Gildenmitglieder, die gerade online sind.",
	["Only items in your bags, bank or on your other characters (from Bags)."] = "Nur Gegenstände in Euren Taschen, der Bank oder auf Euren anderen Charakteren (aus Taschen).",
	["Only items your class, race and professions can use (any level)."] = "Nur Gegenstände, die Eure Klasse, Volk und Berufe benutzen können (jede Stufe).",
	["Only members at level 60."] = "Nur Mitglieder auf Stufe 60.",
	["Only members who have not finished every attunement in the columns."] = "Nur Mitglieder, die nicht jede Einstimmung in den Spalten abgeschlossen haben.",
	["Only places whose level range fits you or is close."] = "Nur Orte, deren Stufenbereich zu Euch passt oder nah ist.",
	["Only quests for your side, race, class and professions."] = "Nur Quests für Eure Seite, Euer Volk, Eure Klasse und Eure Berufe.",
	["Only the moments of one zone. Right-click shows every zone again."] = "Nur die Momente einer Zone. Rechtsklick zeigt wieder jede Zone.",
	["Only the people you ran a dungeon with."] = "Nur die Leute, mit denen Ihr einen Dungeon gelaufen seid.",
	["Only the people you wrote a note on or marked Good or Avoid, with everyone in your player notes."] = "Nur die Leute, über die Ihr eine Notiz geschrieben oder die Ihr als Gut oder Meiden markiert habt, mit allen in Euren Spielernotizen.",
	["Only the zones of the open world."] = "Nur die Zonen der offenen Welt.",
	["Only while on the quest"] = "Nur während der Quest",
	["Open %s in Places"] = "%s in Orte öffnen",
	["Open Catalog > Zones"] = "Katalog > Gebiete öffnen",
	["Open My Adventure"] = "Mein Abenteuer öffnen",
	["Open World"] = "Offene Welt",
	["Open a dungeon in the Journal and press Dungeon map: the floors with numbered boss markers. Entrance pins the way in on your world map."] = "Öffnet einen Dungeon im Tagebuch und drückt Dungeonkarte: die Ebenen mit nummerierten Bossmarkierungen. Eingang markiert den Weg hinein auf Eurer Weltkarte.",
	["Open a quest or a creature from Search or an item page."] = "Öffnet eine Quest oder eine Kreatur über die Suche oder eine Gegenstandsseite.",
	["Open an item from Search, the Journal or your wishlist."] = "Öffnet einen Gegenstand über die Suche, das Tagebuch oder Eure Wunschliste.",
	["Open for you now"] = "Jetzt für Euch offen",
	["Open in Dungeons"] = "In Dungeons öffnen",
	["Open in Journal"] = "Im Tagebuch öffnen",
