	["Open on"] = "Öffnen auf",
	["Open that day"] = "Diesen Tag öffnen",
	["Open the Attunements tab"] = "Den Reiter Einstimmungen öffnen",
	["Open the Book"] = "Das Buch öffnen",
	["Open the Journal"] = "Das Tagebuch öffnen",
	["Open the Journey"] = "Die Reise öffnen",
	["Open the Loot Guide"] = "Den Loot Guide öffnen",
	["Open the dungeon you are in"] = "Den Dungeon öffnen, in dem Ihr seid",
	["Open the map (M) to see the mark."] = "Öffnet die Karte (M), um die Markierung zu sehen.",
	["Open the map there"] = "Die Karte dort öffnen",
	["Open the place"] = "Den Ort öffnen",
	["Open the simulator"] = "Den Simulator öffnen",
	["Opening day badges"] = "Öffnungstag-Markierungen",
	["Opens"] = "Öffnet",
	["Opens EldoUI's keybind mode. My Adventure's keys (open or close it, quick note, the tracker, and Next trips) are also under Options > Keybindings > AddOns > EldoUI."] = "Öffnet den Tastenbelegungsmodus von EldoUI. Die Tasten von Mein Abenteuer (öffnen oder schließen, schnelle Notiz, der Tracker und Nächste Reisen) findet Ihr auch unter Optionen > Tastenbelegung > AddOns > EldoUI.",
	["Opens My Adventure in the Journal window."] = "Öffnet Mein Abenteuer im Tagebuchfenster.",
	["Opens a card that compares the item with what you wear, its source and your plans."] = "Öffnet eine Karte, die den Gegenstand mit dem vergleicht, was Ihr tragt, mit seiner Quelle und Euren Plänen.",
	["Opens a copy box with the Forever quests you took, to send to EldoUI's authors so the dungeon can get a full chain."] = "Öffnet ein Kopierfeld mit den Forever-Quests, die Ihr angenommen habt, zum Senden an die Autoren von EldoUI, damit der Dungeon eine vollständige Kette bekommt.",
	["Opens a copy box with the list, to send to EldoUI's authors so the dungeon can get a full chain."] = "Öffnet ein Kopierfeld mit der Liste, zum Senden an die Autoren von EldoUI, damit der Dungeon eine vollständige Kette bekommt.",
	["Opens at level %d in %s."] = "Ab Stufe %d in %s verfügbar.",
	["Opens at level %d with %s in %s."] = "Beginnt ab Stufe %d bei %s in %s.",
	["Opens at level %d."] = "Beginnt ab Stufe %d.",
	["Opens its page in the Journal."] = "Öffnet seine Seite im Tagebuch.",
	["Opens the Attunements tab on it."] = "Öffnet den Reiter Einstimmungen darauf.",
	["Opens the Attunements tab on this step."] = "Öffnet den Reiter Einstimmungen bei diesem Schritt.",
	["Opens the Best in Slot page with every slot."] = "Öffnet die Seite Best in Slot mit jedem Platz.",
	["Opens the Catalog on Reputation: every faction and its rewards."] = "Öffnet den Katalog bei Ruf: jede Fraktion und ihre Belohnungen.",
	["Opens the Dungeons tab: every dungeon and raid with its bosses, loot and quests."] = "Öffnet den Reiter Dungeons: jeder Dungeon und Schlachtzug mit Bossen, Beute und Quests.",
	["Opens the Journal window on My Adventure."] = "Öffnet das Tagebuchfenster bei Mein Abenteuer.",
	["Opens the Journey with only the moments of this dungeon."] = "Öffnet die Reise nur mit den Momenten dieses Dungeons.",
	["Opens the Journey with only the moments of this place."] = "Öffnet die Reise nur mit den Momenten dieses Ortes.",
	["Opens the Loot Guide's Best in Slot page."] = "Öffnet die Seite Best in Slot des Loot Guide.",
	["Opens the Open World tab: zones, rares and world drops."] = "Öffnet den Reiter Offene Welt: Zonen, seltene Gegner und Weltdrops.",
	["Opens the boss in the Journal."] = "Öffnet den Boss im Tagebuch.",
	["Opens the day you pick in the day view."] = "Öffnet den gewählten Tag in der Tagesansicht.",
	["Opens the dungeon in the Journal on this creature."] = "Öffnet den Dungeon im Tagebuch bei dieser Kreatur.",
	["Opens the dungeon map with its bosses."] = "Öffnet die Dungeonkarte mit ihren Bossen.",
	["Opens the dungeon's quest list on this quest."] = "Öffnet die Questliste des Dungeons bei dieser Quest.",
	["Opens the game's group finder window. Nothing is listed or queued for you."] = "Öffnet das Gruppensuche-Fenster des Spiels. Nichts wird für Euch eingetragen oder angemeldet.",
	["Opens the instance in the Journal: bosses, loot and its quests."] = "Öffnet die Instanz im Tagebuch: Bosse, Beute und ihre Quests.",
	["Opens the item where it drops: the boss, the quest or the item page."] = "Öffnet den Gegenstand dort, wo er fällt: der Boss, die Quest oder die Gegenstandsseite.",
	["Opens the map of this instance with its bosses marked."] = "Öffnet die Karte dieser Instanz mit markierten Bossen.",
	["Opens the place in the Journal."] = "Öffnet den Ort im Tagebuch.",
	["Opens the quest in the Loot Guide: where to get it, what it needs, and its rewards."] = "Öffnet die Quest im Loot Guide: wo man sie bekommt, was sie braucht und ihre Belohnungen.",
	["Opens the spells your class trainer teaches that you don't know yet."] = "Öffnet die Zauber, die Euer Klassenlehrer Euch beibringt und die Ihr noch nicht kennt.",
	["Opens the world map on this zone (out of combat)."] = "Öffnet die Weltkarte bei dieser Zone (außerhalb des Kampfes).",
	["Opens the zone on the World page."] = "Öffnet die Zone auf der Seite Welt.",
	["Opens the zone's rares and creatures."] = "Öffnet die seltenen Gegner und Kreaturen der Zone.",
	["Opens this dungeon among your places in My Adventure."] = "Öffnet diesen Dungeon unter Euren Orten in Mein Abenteuer.",
	["Opens this dungeon on the Dungeons tab: bosses, loot, and quests."] = "Öffnet diesen Dungeon im Reiter Dungeons: Bosse, Beute und Quests.",
	["Opens this instance in the Journal."] = "Öffnet diese Instanz im Tagebuch.",
	["Opens this moment in your journal."] = "Öffnet diesen Moment in Eurem Tagebuch.",
	["Opens this note in the box above."] = "Öffnet diese Notiz im Feld oben.",
	["Opens this part in the Book."] = "Öffnet diesen Teil im Buch.",
	["Optional: leads to %s."] = "Optional: führt zu %s.",
	["Or type its name:"] = "Oder tippt den Namen ein:",
	["Orgrimmar"] = "Orgrimmar",
	["Other chains"] = "Andere Ketten",
	["Other creatures"] = "Andere Kreaturen",
	["Other events"] = "Andere Ereignisse",
	["Other faction"] = "Andere Fraktion",
	["Other sets"] = "Andere Sets",
	["Other side"] = "Andere Seite",
	["Other sources"] = "Andere Quellen",
	["Other talents"] = "Andere Talente",
	["Outdated: your gear, talents, level or the fight settings changed since this run."] = "Veraltet: Eure Ausrüstung, Talente, Stufe oder die Kampfeinstellungen haben sich seit diesem Lauf geändert.",
	["Outdated: your gear, talents, level or the fight settings changed since this run. Press Sim to run it again."] = "Veraltet: Eure Ausrüstung, Talente, Stufe oder die Kampfeinstellungen haben sich seit diesem Lauf geändert. Drückt Sim, um ihn erneut zu starten.",
	["Overview opens on"] = "Übersicht öffnet auf",
	["Owl"] = "Eule",
	["Owned"] = "Im Besitz",
	["Pace"] = "Tempo",
	["Packed?"] = "Gepackt?",
	["Page look"] = "Seitenaussehen",
	["Page turns and the river draw in. Follows General > Animations unless you turn it off here."] = "Umblättern und der Fluss zeichnen sich ein. Folgt Allgemein > Animationen, außer Ihr schaltet es hier aus.",
	["Pages"] = "Seiten",
	["Paper"] = "Papier",
	["Parchment pages with dark ink for the Book and the character card, told as a Chronicle."] = "Pergamentseiten mit dunkler Tinte für das Buch und die Charakterkarte, erzählt als Chronik.",
	["Parchment pages with dark ink, like an old book."] = "Pergamentseiten mit dunkler Tinte, wie ein altes Buch.",
	["Parchment, EldoUI or Night ledger for the Book and the character card."] = "Pergament, EldoUI oder Nachtbuch für das Buch und die Charakterkarte.",
	["Part %d"] = "Teil %d",
