	["Part of attunement"] = "Teil einer Einstimmung",
	["Part of your next trip"] = "Teil Eurer nächsten Reise",
	["Part of: %s (%d/%d)"] = "Teil von: %s (%d/%d)",
	["Party %d"] = "Gruppe %d",
	["Paste a journal backup code: !EUJ1! from EldoUI or FJ1: from Forever Journal. You see what it holds before anything changes."] = "Fügt einen Tagebuch-Sicherungscode ein: !EUJ1! aus EldoUI oder FJ1: aus Forever Journal. Ihr seht, was er enthält, bevor sich etwas ändert.",
	["Paste a journal code"] = "Tagebuch-Code einfügen",
	["Paste a runs code"] = "Durchlaufcode einfügen",
	["Paste a runs code from EldoUI (!EUJR1!). You see what it holds before anything changes."] = "Fügt einen Durchlaufcode aus EldoUI ein (!EUJR1!). Ihr seht, was er enthält, bevor sich etwas ändert.",
	["Paste a wishlist string (Ctrl+V) and click Save."] = "Fügt einen Wunschlisten-Text ein (Strg+V) und klickt auf Speichern.",
	["Paste it into a journal-data issue. It changes nothing in your game."] = "Fügt ihn in ein Journal-Data-Issue ein. Er ändert nichts in Eurem Spiel.",
	["Paused for combat. The run goes on when combat ends."] = "Wegen Kampf pausiert. Der Lauf geht weiter, wenn der Kampf endet.",
	["People"] = "Leute",
	["People you grouped with long enough for the journal to remember."] = "Leute, mit denen Ihr lange genug gruppiert wart, dass sich das Tagebuch an sie erinnert.",
	["People you grouped with long enough for the journal to remember. Names show while Name companions is on."] = "Leute, mit denen Ihr lange genug gruppiert wart, dass sich das Tagebuch an sie erinnert. Namen erscheinen, solange Gefährten nennen an ist.",
	["People you meet and group with, group quests and your guild."] = "Leute, die Ihr trefft und mit denen Ihr in einer Gruppe seid, Gruppenquests und Eure Gilde.",
	["Pick a backup of your runs, then Merge or Replace. Your runs are backed up first."] = "Wählt eine Sicherung Eurer Durchläufe, dann Zusammenführen oder Ersetzen. Eure Durchläufe werden vorher gesichert.",
	["Pick a backup, then Merge (keeps everything since) or Replace (exactly as it was). Your journal is backed up first."] = "Wählt eine Sicherung, dann Zusammenführen (behält alles seither) oder Ersetzen (genau wie damals). Euer Tagebuch wird vorher gesichert.",
	["Pick a craft to see its reagents and where the recipe comes from."] = "Wählt ein Rezept, um seine Reagenzien zu sehen und woher das Rezept stammt.",
	["Pick a craft: its reagents with what you own and where the recipe comes from, with Map buttons."] = "Wählt ein Rezept: seine Reagenzien mit dem, was Ihr besitzt, und woher das Rezept stammt, mit Kartenknöpfen.",
	["Pick a faction on the left."] = "Wählt links eine Fraktion.",
	["Pick a level above the one you have."] = "Wählt eine Stufe über Eurer aktuellen.",
	["Pick a quest on the left to see its chain, objectives and rewards."] = "Wählt links eine Quest, um ihre Reihe, Ziele und Belohnungen zu sehen.",
	["Pick a row to see it here."] = "Wählt eine Zeile, um sie hier zu sehen.",
	["Pick a zone"] = "Zone wählen",
	["Pick an attunement from the list, or type its name."] = "Wählt eine Einstimmung aus der Liste oder tippt ihren Namen ein.",
	["Pick an item from your wishlist."] = "Wählt einen Gegenstand aus Eurer Wunschliste.",
	["Pick the list the stars add to, show other lists, make, rename, share or delete lists."] = "Wählt die Liste, zu der die Sterne hinzufügen, zeigt andere Listen, erstellt, benennt um, teilt oder löscht Listen.",
	["Pick the target dummy's level and the fight length. Bosses are three levels above you."] = "Wählt die Stufe der Trainingsattrappe und die Kampfdauer. Bosse sind drei Stufen über Euch.",
	["Pick up a quest and it shows here until you hand it in."] = "Nehmt eine Quest an, dann erscheint sie hier, bis Ihr sie abgebt.",
	["Pick up its quests before you go."] = "Holt Euch vor dem Aufbruch seine Quests.",
	["Pick up: %s"] = "Annehmen: %s",
	["Pick what you want to work towards."] = "Wählt, worauf Ihr hinarbeiten wollt.",
	["Picked up %s · %s ago"] = "Angenommen am %s · vor %s",
	["Picked up %s · handed in %s · took %s"] = "Angenommen am %s · abgegeben am %s · Dauer %s",
	["Picked up in %s"] = "Angenommen in %s",
	["Picks new wording for the whole Book. The facts don't change."] = "Wählt neue Formulierungen für das ganze Buch. Die Fakten ändern sich nicht.",
	["Picks new wording for the whole story. The facts don't change."] = "Wählt neue Formulierungen für die ganze Geschichte. Die Fakten ändern sich nicht.",
	["Pin"] = "Anheften",
	["Pin new notes to the Journey"] = "Neue Notizen an die Reise heften",
	["Pin to Journey"] = "An die Reise heften",
	["Pinned"] = "Angeheftet",
	["Pinned notes"] = "Angeheftete Notizen",
	["Pins at dungeon and raid entrances on the world and zone maps, with the level range and your upgrades inside. Where the game draws its own entrance pin, ours steps aside, so no entrance shows twice."] = "Markierungen an Dungeon- und Schlachtzugseingängen auf Welt- und Zonenkarte, mit Stufenbereich und Euren Verbesserungen darin. Wo das Spiel selbst einen Eingang einzeichnet, blendet sich unsere Markierung aus, damit kein Eingang doppelt erscheint.",
	["Pins for the givers of quests you can pick up now."] = "Markierungen für die Questgeber der Quests, die Ihr jetzt annehmen könnt.",
	["Pins the biggest of %d camps on your map. Click again for the next one; after the last the pin goes away."] = { one = "Markiert das größte von %d Lagern auf Eurer Karte. Klickt erneut für das nächste; nach dem letzten verschwindet die Markierung.", other = "Markiert das größte von %d Lagern auf Eurer Karte. Klickt erneut für das nächste; nach dem letzten verschwindet die Markierung." },
	["Pins the dungeon's entrance on your map."] = "Markiert den Eingang des Dungeons auf Eurer Karte.",
	["Pins the entrance in %s on your map and turns on the arrow."] = "Markiert den Eingang in %s auf Eurer Karte und schaltet den Pfeil ein.",
	["Pins the entrance on your map and opens the map there (out of combat)."] = "Markiert den Eingang auf Eurer Karte und öffnet dort die Karte (außerhalb des Kampfes).",
	["Pins the entrance on your map."] = "Markiert den Eingang auf Eurer Karte.",
	["Pins the instance entrance on your map and turns on the arrow."] = "Markiert den Instanzeingang auf Eurer Karte und schaltet den Pfeil ein.",
	["Pins the instance entrance on your map, turns on the arrow and opens the map there (out of combat)."] = "Markiert den Instanzeingang auf Eurer Karte, schaltet den Pfeil ein und öffnet dort die Karte (außerhalb des Kampfes).",
	["Pins the place on your map and turns on the arrow."] = "Markiert den Ort auf Eurer Karte und schaltet den Pfeil ein.",
	["Pins the place on your map and turns on the arrow. Click again to take the pin away."] = "Markiert den Ort auf Eurer Karte und schaltet den Pfeil ein. Klickt erneut, um die Markierung zu entfernen.",
	["Places"] = "Orte",
	["Places and dungeons"] = "Orte und Dungeons",
	["Places the boss markers by where the creatures stand in the Classic data, on a plain grid. Approximate: walls and floors are not drawn."] = "Setzt die Bossmarkierungen dorthin, wo die Kreaturen laut Classic-Daten stehen, auf ein einfaches Raster. Ungefähr: Wände und Böden werden nicht gezeichnet.",
	["Plan"] = "Plan",
	["Plan pieces to see the total and how many weeks of your recent honor each one takes."] = "Plant Teile, um die Summe zu sehen und wie viele Wochen Eurer letzten Ehre jedes kostet.",
	["Plan set"] = "Planset",
	["Plan set %d"] = "Planset %d",
	["Plan the trip"] = "Die Reise planen",
	["Plan with what WoW: Forever has open now, or with an announced step such as the December raids: loot up to that step counts. Now follows the announced days."] = "Plant mit dem, was WoW: Forever jetzt geöffnet hat, oder mit einem angekündigten Schritt wie den Dezember-Schlachtzügen: Beute bis zu diesem Schritt zählt. Jetzt folgt den angekündigten Tagen.",
	["Plan: %s"] = "Plan: %s",
	["Plan: now"] = "Plan: jetzt",
	["Planned"] = "Geplant",
	["Planner"] = "Planer",
	["Plate"] = "Platte",
	["Play when game effects are muted"] = "Abspielen, wenn Spieleffekte stumm sind",
	["Played for %s"] = "Gespielt: %s",
	["Plays moment sounds on the Master channel."] = "Spielt Momentklänge über den Hauptkanal ab.",
	["Plays with the toast for a finished attunement. Step toasts are silent."] = "Erklingt mit der Einblendung für eine abgeschlossene Einstimmung. Schritt-Einblendungen sind still.",
	["Plays with this kind of moment. None: the card stays quiet."] = "Erklingt bei dieser Art Moment. Keiner: Die Karte bleibt still.",
	["Poor (gray)"] = "Schlecht (grau)",
	["Posts one line in guild chat."] = "Schreibt eine Zeile in den Gildenchat.",
	["Press %s to take a screenshot. Click or press Esc to close."] = "Drückt %s für einen Screenshot. Klickt oder drückt Esc zum Schließen.",
	["Press Ctrl+C to copy it, save it as a .html file and open it in a browser. Print it to PDF for a keepsake."] = "Drückt Strg+C zum Kopieren, speichert es als .html-Datei und öffnet es in einem Browser. Druckt es als PDF als Andenken.",
	["Press Ctrl+C to copy it, then paste it anywhere."] = "Drückt Strg+C zum Kopieren und fügt es irgendwo ein.",
	["Press Ctrl+C to copy it, then paste it into any Markdown editor or note app."] = "Drückt Strg+C zum Kopieren und fügt es in einen Markdown-Editor oder eine Notiz-App ein.",
	["Press Ctrl+C to copy the code. Use \"Paste a journal code\" on this PC or another to restore the journal. Nothing is sent anywhere."] = "Drückt Strg+C, um den Code zu kopieren. Nutzt \"Tagebuch-Code einfügen\" auf diesem oder einem anderen PC, um das Tagebuch wiederherzustellen. Nichts wird irgendwohin gesendet.",
	["Press Ctrl+C to copy the code. Use \"Paste a runs code\" on this PC or another to restore your runs. Nothing is sent anywhere."] = "Drückt Strg+C, um den Code zu kopieren. Nutzt \"Durchlaufcode einfügen\" auf diesem oder einem anderen PC, um Eure Durchläufe wiederherzustellen. Nichts wird irgendwohin gesendet.",
	["Press Ctrl+C to copy. Nothing is sent anywhere: paste it where you like."] = "Drückt Strg+C zum Kopieren. Nichts wird irgendwohin gesendet: Fügt es ein, wo Ihr wollt.",
	["Press Ctrl+C to copy. Paste it back in with Paste a journal code, on this PC or another. Nothing is sent anywhere."] = "Drückt Strg+C zum Kopieren. Fügt es mit Tagebuch-Code einfügen wieder ein, auf diesem oder einem anderen PC. Nichts wird irgendwohin gesendet.",
	["Press Sim to compare the checked sets in the same fights."] = "Drückt Sim, um die angehakten Sets in denselben Kämpfen zu vergleichen.",
	["Press Sim to read your character and fight a target dummy 120 times. It takes a few seconds and runs out of combat."] = "Drückt Sim, um Euren Charakter zu lesen und 120-mal gegen eine Trainingsattrappe zu kämpfen. Das dauert ein paar Sekunden und läuft außerhalb des Kampfes.",
	["Previous pages"] = "Vorige Seiten",
	["Prints where the loot data comes from (same as /lg data)."] = "Gibt aus, woher die Beutedaten stammen (wie /lg data).",
	["Prints where the loot data comes from, its version and size (same as /lg data)."] = "Gibt aus, woher die Beutedaten stammen, ihre Version und Größe (wie /lg data).",
	["Profession mastered"] = "Beruf gemeistert",
	["Profession needed"] = "Beruf benötigt",
	["Professions and skills"] = "Berufe und Fertigkeiten",
	["Protection: Shield Slam and Sunder Armor"] = "Schutz: Schildschlag und Rüstung zerreißen",
	["Providers:"] = "Anbieter:",
	["Put away (%d)"] = "Weggelegt (%d)",
	["Put away until your next break."] = "Bis zu Eurer nächsten Pause weggelegt.",
	["Put away until your next level or for 24 hours."] = "Bis zu Eurer nächsten Stufe oder für 24 Stunden weggelegt.",
	["Put in %s"] = "In %s legen",
	["Put in chat"] = "In den Chat",
	["Put on %s"] = "Angelegt: %s",
	["Put on %s in %s"] = "Angelegt: %s in %s",
	["Puts a group line into the chat box. Nothing is sent until you press Enter."] = "Schreibt eine Gruppenzeile ins Chatfeld. Nichts wird gesendet, bis Ihr die Eingabetaste drückt.",
	["Puts every journal the last import touched back as it was before, and its settings too."] = "Stellt jedes Tagebuch, das der letzte Import berührt hat, so wieder her, wie es vorher war, auch seine Einstellungen.",
	["Puts every piece you do not have on your active wishlist."] = "Setzt jedes Teil, das Ihr nicht habt, auf Eure aktive Wunschliste.",
	["Puts its quests that are already in your log on the objective tracker. Nothing is accepted for you."] = "Setzt seine Quests, die schon in Eurem Questlog sind, in die Zielverfolgung. Nichts wird für Euch angenommen.",
	["Puts one line about your character in the chat box. You read it and press Enter to send it."] = "Schreibt eine Zeile über Euren Charakter ins Chatfeld. Ihr lest sie und drückt die Eingabetaste, um sie zu senden.",
	["Puts the item in this plan set on the Best in Slot page, or takes it out. Plan sets are plans, not equipment sets."] = "Nimmt den Gegenstand in dieses Planset auf der Seite Best in Slot auf oder entfernt ihn. Plansets sind Pläne, keine Ausrüstungssets.",
	["Puts the item link into the chat line you are typing in."] = "Fügt den Gegenstandslink in die Chatzeile ein, in der Ihr schreibt.",
	["Puts the window back at the top of the screen at normal size."] = "Setzt das Fenster in normaler Größe zurück an den oberen Bildschirmrand.",
	["Puts this card away until your next break."] = "Legt diese Karte bis zu Eurer nächsten Pause weg.",
	["Puts this card away until your next level or for 24 hours."] = "Legt diese Karte bis zu Eurer nächsten Stufe oder für 24 Stunden weg.",
	["Puts this card away."] = "Legt diese Karte weg.",
	["Puts this goal back on the page."] = "Holt dieses Ziel zurück auf die Seite.",
	["Puts this note back on the page."] = "Holt diese Notiz zurück auf die Seite.",
	["Puts this quest back on the page."] = "Holt diese Quest zurück auf die Seite.",
	["PvP armor"] = "PvP-Rüstung",
	["PvP class sets"] = "PvP-Klassensets",
	["PvP is off in your filter"] = "PvP ist in Eurem Filter aus",
	["PvP rewards come from EldoUI_LootData. Install it next to EldoUI to list them."] = "PvP-Belohnungen stammen aus EldoUI_LootData. Installiert es neben EldoUI, um sie aufzulisten.",
	["PvP sets"] = "PvP-Sets",
	["PvP weapons"] = "PvP-Waffen",
	["PvP: honor per week"] = "PvP: Ehre pro Woche",
	["Quartermasters"] = "Rüstmeister",
	["Quest Starter Drops"] = "Questbeginner-Beute",
	["Quest chain"] = "Questreihe",
	["Quest choice: %s"] = "Questauswahl: %s",
	["Quest count in the zone tooltip"] = "Questanzahl im Gebiets-Tooltip",
	["Quest giver"] = "Questgeber",
	["Quest givers on the map"] = "Questgeber auf der Karte",
	["Quest icons"] = "Questsymbole",
	["Quest icons on bronze, to match the WoW Forever art style."] = "Questsymbole auf Bronze, passend zum Kunststil von WoW Forever.",
	["Quest icons on the map for quests you can take now; everything listed."] = "Questsymbole auf der Karte für Quests, die Ihr jetzt annehmen könnt; alles aufgelistet.",
	["Quest items, weapons, armor, accessories and the rest, each with the most likely drop first."] = "Questgegenstände, Waffen, Rüstung, Accessoires und der Rest, jeweils mit der wahrscheinlichsten Beute zuerst.",
	["Quest level %d"] = "Queststufe %d",
	["Quest reward"] = "Questbelohnung",
	["Quest reward: %s"] = "Questbelohnung: %s",
	["Quest rewards, dungeon and raid drops and crafted gear."] = "Questbelohnungen, Dungeon- und Schlachtzugsbeute und hergestellte Ausrüstung.",
	["Quest, level %d"] = "Quest, Stufe %d",
	["Questions, ideas or a wrong drop? Copy this address (Ctrl+C) and open it in your browser."] = "Fragen, Ideen oder eine falsche Beute? Kopiert diese Adresse (Strg+C) und öffnet sie in Eurem Browser.",
	["Quests %s"] = "Quests %s",
	["Quests above your level"] = "Quests über Eurer Stufe",
	["Quests above your level by more than this are not suggested."] = "Quests, die mehr als so viele Stufen über Eurer liegen, werden nicht vorgeschlagen.",
	["Quests and companions"] = "Quests und Gefährten",
	["Quests are quicker with company. These fit your level:"] = "Quests gehen mit Begleitung schneller. Diese passen zu Eurer Stufe:",
	["Quests for you"] = "Quests für Euch",
	["Quests grouped by"] = "Quests gruppiert nach",
	["Quests handed in"] = "Abgegebene Quests",
	["Quests handed in here"] = "Hier abgegebene Quests",
	["Quests that left your log without a hand-in: abandoned, failed, or removed by the game. With where and when you took each one."] = "Quests, die Euer Log ohne Abgabe verlassen haben: abgebrochen, gescheitert oder vom Spiel entfernt. Mit Ort und Zeit, wann Ihr jede angenommen habt.",
	["Quests that need a prerequisite"] = "Quests mit Vorquest",
	["Quests that reward the item, need it or start from it."] = "Quests, die den Gegenstand belohnen, ihn brauchen oder mit ihm beginnen.",
	["Quests that reward the item, need it, or start from it."] = "Quests, die den Gegenstand belohnen, ihn brauchen oder mit ihm beginnen.",
	["Quests the game remembers you finished before the journal began. The game does not say when."] = "Quests, die Ihr laut Spiel vor Beginn des Tagebuchs abgeschlossen habt. Das Spiel sagt nicht, wann.",
	["Quests to hand in, attunements under way, your goals, reminders, and mail that runs out soon."] = "Abzugebende Quests, laufende Einstimmungen, Eure Ziele, Erinnerungen und Post, die bald abläuft.",
	["Quests to hand in, quests in your log by zone, and quest chains to go on with."] = "Abzugebende Quests, Quests in Eurem Log nach Zone und Questreihen zum Weitermachen.",
	["Quests together"] = "Gemeinsame Quests",
	["Quests you can take now"] = "Quests, die Ihr jetzt annehmen könnt",
	["Quests you handed in at these levels."] = "Quests, die Ihr auf diesen Stufen abgegeben habt.",
	["Quests you have taken for it"] = "Quests, die Ihr dafür angenommen habt",
	["Quests, crafted and other"] = "Quests, Hergestelltes und anderes",
	["Quests, dungeons, crafted, vendors and reputation; no rares, world drops or PvP; every drop chance; every armor kind you wear."] = "Quests, Dungeons, Hergestelltes, Händler und Ruf; keine seltenen Gegner, Weltdrops oder PvP; jede Beutechance; jede Rüstungsart, die Ihr tragt.",
	["Quick note"] = "Schnelle Notiz",
	["Raid %d"] = "Schlachtzug %d",
	["Raid attunement"] = "Schlachtzugs-Einstimmung",
	["Raid boss down"] = "Schlachtzugsboss besiegt",
	["Raids and the world bosses."] = "Schlachtzüge und die Weltbosse.",
	["Raids join the suggestions (the Include raids setting of My Adventure)."] = "Schlachtzüge kommen zu den Vorschlägen hinzu (die Einstellung Schlachtzüge einbeziehen von Mein Abenteuer).",
	["Raids open near the level cap. Turn on raids in the settings to see them here."] = "Schlachtzüge öffnen sich nahe der Höchststufe. Schaltet Schlachtzüge in den Einstellungen ein, um sie hier zu sehen.",
	["Raids open near the level cap. Until then, these dungeons fit your level:"] = "Schlachtzüge öffnen sich nahe der Höchststufe. Bis dahin passen diese Dungeons zu Eurer Stufe:",
	["Raise a profession"] = "Einen Beruf steigern",
	["Ran %s again"] = "%s erneut gelaufen",
