	["Rank %d"] = "Rang %d",
	["Rank as if you play on your own."] = "Rangfolge, als ob Ihr allein spielt.",
	["Rank for a full group of five."] = "Rangfolge für eine volle Fünfergruppe.",
	["Rank for a raid group."] = "Rangfolge für eine Schlachtzugsgruppe.",
