	["Ranking your items..."] = "Eure Gegenstände werden eingestuft...",
	["Ranking..."] = "Wird eingestuft...",
	["Raptor"] = "Raptor",
	["Rare creatures roam every zone. The Open World tab lists them by zone."] = "Rare Kreaturen streifen durch jede Zone. Der Reiter Offene Welt listet sie nach Zone.",
	["Rare creatures roam the zones for your level. These fit you:"] = "Rare Kreaturen streifen durch die Zonen Eurer Stufe. Diese passen zu Euch:",
	["Rare drop"] = "Seltene Beute",
	["Rare mobs, world drops, zone quests and vendors by zone, for leveling between dungeons."] = "Rare Gegner, Weltdrops, Zonenquests und Händler nach Zone, zum Leveln zwischen Dungeons.",
	["Rare spawn"] = "Rarer Gegner",
	["Rares"] = "Rare",
	["Rares and creatures by zone: their best drops for you, their camps on your map and which rares the game shows near you now."] = "Rare Gegner und Kreaturen nach Zone: ihre beste Beute für Euch, ihre Lager auf Eurer Karte und welche seltenen Gegner das Spiel gerade in Eurer Nähe zeigt.",
	["Rares, creatures and their camps come from EldoUI_LootData. Install it next to EldoUI and reload."] = "Rare Gegner, Kreaturen und ihre Lager stammen aus EldoUI_LootData. Installiert es neben EldoUI und ladet neu.",
	["Ratchet"] = "Ratschet",
	["Rated by your spec's stat weights, the same numbers the Upgrades arrows show."] = "Bewertet nach den Wertgewichten Eurer Spezialisierung, denselben Zahlen, die die Verbesserungspfeile zeigen.",
	["Rates every item you can get with the simulator. It runs in small steps out of combat."] = "Bewertet jeden Gegenstand, den Ihr bekommen könnt, mit dem Simulator. Er läuft in kleinen Schritten außerhalb des Kampfes.",
	["Rates items for this character by these fights (Rate items by: Simulator). You can switch back on the Loot Guide settings page."] = "Bewertet Gegenstände für diesen Charakter nach diesen Kämpfen (Gegenstände bewerten nach: Simulator). Ihr könnt auf der Einstellungsseite des Loot Guide zurückwechseln.",
	["Rating the gear you can get..."] = "Die erreichbare Ausrüstung wird bewertet...",
