	["Show one kind of moment: growth, gear, deeds, places, people, or notes."] = "Eine Art von Moment zeigen: Wachstum, Ausrüstung, Taten, Orte, Leute oder Notizen.",
	["Show quests for"] = "Quests anzeigen für",
