	["Show the %s page in the Loot Guide window."] = "Die Seite %s im Fenster des Loot Guide zeigen.",
	["Show the %s page in the Loot Guide window. Hiding it also hides gain marks in lists and plan sets in tooltips."] = "Die Seite %s im Fenster des Loot Guide zeigen. Ausblenden versteckt auch die Gewinnmarken in Listen und die Plansets in Tooltips.",
	["Show the %s page in the Loot Guide window. Hiding it also hides the wishlist stars and tooltip line."] = "Die Seite %s im Fenster des Loot Guide zeigen. Ausblenden versteckt auch die Wunschlisten-Sterne und die Tooltipzeile.",
	["Show the quests in progress"] = "Laufende Quests zeigen",
