	["Show what this token buys"] = "Zeigen, was diese Marke kauft",
	["Showing the first %d items. Type more to narrow it down."] = "Die ersten %d Gegenstände werden gezeigt. Tippt mehr, um einzugrenzen.",
	["Shown here and used for upgrades when Rate items by is Simulator. Estimates: set bonuses and item procs are not counted."] = "Wird hier gezeigt und für Verbesserungen genutzt, wenn Gegenstände bewerten nach auf Simulator steht. Schätzungen: Setboni und Gegenstandseffekte werden nicht gezählt.",
	["Shows a level moment the way it looks with your settings."] = "Zeigt einen Stufenmoment so, wie er mit Euren Einstellungen aussieht.",
