	["Shows an item tooltip with the Loot Guide lines, so you can see your settings."] = "Zeigt einen Gegenstands-Tooltip mit den Zeilen des Loot Guide, damit Ihr Eure Einstellungen seht.",
	["Shows both factions, every class and content the game does not list yet."] = "Zeigt beide Fraktionen, jede Klasse und Inhalte, die das Spiel noch nicht listet.",
