	["Shows every place again."] = "Zeigt wieder jeden Ort.",
	["Shows gain marks, plan sets and upgrades again."] = "Zeigt Gewinnmarken, Plansets und Verbesserungen wieder.",
	["Shows how much the item would gain you beside each loot roll. Advice only: you always roll yourself."] = "Zeigt neben jedem Beutewurf, wie viel der Gegenstand Euch bringen würde. Nur ein Rat: Ihr würfelt immer selbst.",
	["Shows on the Attunements tab how many attunements, steps and quests are loaded and the data version."] = "Zeigt im Reiter Einstimmungen, wie viele Einstimmungen, Schritte und Quests geladen sind, und die Datenversion.",
	["Shows only instances within the level window of yours (Loot Guide settings)."] = "Zeigt nur Instanzen innerhalb Eures Stufenfensters (Einstellungen des Loot Guide).",
	["Shows only items that beat what you wear, rated by the shared item engine."] = "Zeigt nur Gegenstände, die besser sind als das, was Ihr tragt, bewertet von der gemeinsamen Gegenstandslogik.",
	["Shows only rares and creatures that drop an upgrade for you."] = "Zeigt nur seltene Gegner und Kreaturen, die eine Verbesserung für Euch fallen lassen.",
	["Shows only rewards that beat what you wear."] = "Zeigt nur Belohnungen, die besser sind als das, was Ihr tragt.",
	["Shows only this armor kind. Click again for all."] = "Zeigt nur diese Rüstungsart. Klickt erneut für alle.",
	["Shows that attunement."] = "Zeigt diese Einstimmung.",
	["Shows the attunements before these as columns."] = "Zeigt die vorigen Einstimmungen als Spalten.",
	["Shows the item on your character in the dressing room."] = "Zeigt den Gegenstand an Eurem Charakter in der Anprobe.",
	["Shows the nearest %d quests of the chain."] = { one = "Zeigt die %d Quest der Reihe, die am nächsten liegt.", other = "Zeigt die %d Quests der Reihe, die am nächsten liegen." },
	["Shows the next attunements as columns."] = "Zeigt die nächsten Einstimmungen als Spalten.",
