	["Shows this floor. Your pick is remembered for this dungeon."] = "Zeigt diese Ebene. Eure Wahl wird für diesen Dungeon gemerkt.",
	["Shows this note on your Journey, under the level you wrote it at."] = "Zeigt diese Notiz auf Eurer Reise, unter der Stufe, auf der Ihr sie geschrieben habt.",
	["Shows what the tab has loaded, here in the window."] = "Zeigt hier im Fenster, was der Reiter geladen hat.",
