	["Spec"] = "Spezialisierung",
	["Spec, armor, sources and the lowest drop chance your list counts."] = "Spezialisierung, Rüstung, Quellen und die niedrigste Beutechance, die Eure Liste zählt.",
	["Spec, armor, sources, lowest drop chance and stat priority: what counts as your gear everywhere in EldoUI."] = "Spezialisierung, Rüstung, Quellen, niedrigste Beutechance und Wertepriorität: was überall in EldoUI als Eure Ausrüstung zählt.",
	["Spell crit (1 %)"] = "Zauberkrit (1 %)",
	["Spell hit (1 %)"] = "Zaubertreffer (1 %)",
	["Spells and ranks"] = "Zauber und Ränge",
	["Spells not simulated"] = "Nicht simulierte Zauber",
	["Spider"] = "Spinne",
	["Standings"] = "Rufstufen",
	["Star items anywhere to wish for them. You get an alert when one drops, is in a roll or in the dungeon you enter."] = "Markiert Gegenstände überall mit einem Stern, um sie Euch zu wünschen. Ihr bekommt einen Hinweis, wenn einer fällt, ausgewürfelt wird oder im Dungeon ist, den Ihr betretet.",
	["Star items in the Journal, Search or any list and the places to get them show here."] = "Markiert Gegenstände im Tagebuch, in der Suche oder in einer Liste mit einem Stern, dann erscheinen hier die Orte, an denen Ihr sie bekommt.",
	["Start and finish"] = "Anfang und Ende",
	["Start tour"] = "Tour starten",
	["Started without a quest giver"] = "Ohne Questgeber begonnen",
	["Starts"] = "Beginnt",
	["Starts at %s"] = "Beginnt bei %s",
	["Stat priority"] = "Wertepriorität",
	["Stat priority: drag a stat to change the order. Default order takes your change back."] = "Wertepriorität: Zieht einen Wert, um die Reihenfolge zu ändern. Standardreihenfolge nimmt Eure Änderung zurück.",
	["Stats"] = "Werte",
	["Status: ? ready, ! open, x locked, - too low or not for you, v done."] = "Status: ? bereit, ! offen, x gesperrt, - zu niedrig oder nichts für Euch, v erledigt.",
	["Step %d of %d: %s"] = "Schritt %d von %d: %s",
	["Step %d: %s"] = "Schritt %d: %s",
	["Step alerts"] = "Schritt-Hinweise",
	["Step done"] = "Schritt erledigt",
	["Step list"] = "Schrittliste",
	["Step quests the game has no title for (removed or renumbered on WoW: Forever). Copy it (Ctrl+C) and send it to EldoUI's authors."] = "Schrittquests, für die das Spiel keinen Titel hat (auf WoW: Forever entfernt oder neu nummeriert). Kopiert sie (Strg+C) und sendet sie an die Autoren von EldoUI.",
	["Steps"] = "Schritte",
	["Steps the number down. Shift-click steps ten times as far."] = "Verringert die Zahl. Umschaltklick ändert zehnmal so weit.",
	["Steps the number up. Shift-click steps ten times as far."] = "Erhöht die Zahl. Umschaltklick ändert zehnmal so weit.",
	["Still ahead."] = "Liegt noch vor Euch.",
	["Still open: %s."] = "Noch offen: %s.",
	["Still to do"] = "Noch zu tun",
	["Stops the run. Results saved so far stay."] = "Stoppt den Lauf. Bisher gespeicherte Ergebnisse bleiben.",
	["Stops the simulator run. Results saved so far stay."] = "Stoppt den Simulatorlauf. Bisher gespeicherte Ergebnisse bleiben.",
	["Stops this reminder."] = "Beendet diese Erinnerung.",
	["Stormpike Guard"] = "Sturmlanzengarde",
	["Stormstrike, Earth Shock and Windfury"] = "Sturmschlag, Erdschock und Windzorn",
	["Stormwind"] = "Stormwind",
	["Stormwind City"] = "Stormwind",
	["Story"] = "Geschichte",
	["Story lines in chapters"] = "Erzählzeilen in Kapiteln",
	["Story motion"] = "Bewegung der Geschichte",
	["Story so far"] = "Die Geschichte bisher",
	["Storyteller"] = "Erzähler",
	["Style follows the layout"] = "Stil folgt dem Layout",
	["Suggest"] = "Vorschlagen",
	["Suggest raids"] = "Schlachtzüge vorschlagen",
	["Suggest raids too"] = "Auch Schlachtzüge vorschlagen",
	["Suggestions"] = "Vorschläge",
	["Suggestions from other parts of EldoUI and from plugins."] = "Vorschläge aus anderen Teilen von EldoUI und aus Plugins.",
	["Suggestions lean to"] = "Vorschläge neigen zu",
	["Switched off."] = "Ausgeschaltet.",
	["Switches the Alts module on. Each character is added the next time you log in on it."] = "Schaltet das Modul Charaktere ein. Jeder Charakter wird beim nächsten Einloggen mit ihm hinzugefügt.",
	["Switches the Loot Guide module on; My Adventure comes with it."] = "Schaltet das Modul Loot Guide ein; Mein Abenteuer kommt mit.",
	["Switches the Loot Guide module on; quest starter hints come with it."] = "Schaltet das Modul Loot Guide ein; die Hinweise auf Questbeginner kommen mit.",
	["Switches the Loot Guide module on; the Attunements tab comes with it."] = "Schaltet das Modul Loot Guide ein; der Reiter Einstimmungen kommt mit.",
	["Switches the Loot Guide module on; the Zones section comes with it."] = "Schaltet das Modul Loot Guide ein; der Bereich Gebiete kommt mit.",
	["Switches the table. Each table keeps its search and filters for this session."] = "Wechselt die Tabelle. Jede Tabelle behält für diese Sitzung ihre Suche und Filter.",
	["Tabard"] = "Wappenrock",
	["Tabards"] = "Wappenröcke",
	["Take a screenshot with your screenshot key. Click or press Esc to close."] = "Nehmt mit Eurer Screenshot-Taste einen Screenshot auf. Klickt oder drückt Esc zum Schließen.",
	["Take the tour"] = "Die Tour machen",
	["Taken"] = "Angenommen",
	["Taken at %s. You find it in the Screenshots folder of your game."] = "Aufgenommen um %s. Ihr findet ihn im Ordner Screenshots Eures Spiels.",
	["Taken before the journal kept track."] = "Angenommen, bevor das Tagebuch mitschrieb.",
	["Taken off your keepsakes."] = "Aus den Andenken genommen.",
	["Takes a backup of this journal now."] = "Legt jetzt eine Sicherung dieses Tagebuchs an.",
	["Takes about %d minutes."] = { one = "Dauert etwa %d Minute.", other = "Dauert etwa %d Minuten." },
	["Takes it off your keepsakes."] = "Nimmt es aus den Andenken.",
	["Takes one screenshot of the card, without this button and the hint. It goes to the Screenshots folder of your game."] = "Nimmt einen Screenshot der Karte auf, ohne diesen Knopf und den Hinweis. Er landet im Ordner Screenshots Eures Spiels.",
	["Takes step %d: %s"] = "Nimmt Schritt %d an: %s",
	["Takes this note off your Journey."] = "Nimmt diese Notiz von Eurer Reise.",
	["Taking it with you"] = "Mitnehmen",
	["Talent re-specs"] = "Talentrücksetzungen",
	["Talents are read by name, which works on English game clients only. On this client the simulator plays without talent effects."] = "Talente werden über ihren Namen gelesen, was nur mit englischen Spielclients klappt. Auf diesem Client spielt der Simulator ohne Talenteffekte.",
	["Talents the simulator plays"] = "Talente, die der Simulator spielt",
	["Tallstrider"] = "Weitschreiter",
	["Tameable"] = "Zähmbar",
	["Tameable: %s"] = "Zähmbar: %s",
	["Tank: avoidance pick (%s holds more threat)"] = "Tank: Wahl für Vermeidung (%s hält mehr Bedrohung)",
	["Tank: close call with %s"] = "Tank: knapp vor %s",
	["Tank: threat pick (%s holds more avoidance)"] = "Tank: Wahl für Bedrohung (%s hat mehr Vermeidung)",
	["Teaches"] = "Lehrt",
	["Tell the guild"] = "Der Gilde sagen",
	["Tell the guild button"] = "Schaltfläche „Der Gilde sagen“",
	["Telling"] = "Erzählen",
	["Tells you when a wishlist item is in a loot window or a roll, or drops in the dungeon you enter. It never loots or rolls for you."] = "Sagt Euch, wenn ein Gegenstand der Wunschliste in einem Beutefenster oder einem Wurf ist oder im Dungeon fällt, den Ihr betretet. Er plündert oder würfelt nie für Euch.",
	["Test alert"] = "Testhinweis",
	["Text size of the story in the Book and Story so far, 90 to 140%."] = "Textgröße der Geschichte im Buch und in Die Geschichte bisher, 90 bis 140 %.",
	["That backup is gone."] = "Diese Sicherung gibt es nicht mehr.",
	["That dungeon is not in the dungeon list."] = "Dieser Dungeon ist nicht in der Dungeonliste.",
	["That goal could not be set."] = "Dieses Ziel konnte nicht gesetzt werden.",
	["That is not a Forever Journal backup code (it starts with FJ1:)."] = "Das ist kein Sicherungscode von Forever Journal (er beginnt mit FJ1:).",
	["That is not a journal code. A journal code starts with !EUJ1! (EldoUI) or FJ1: (Forever Journal)."] = "Das ist kein Tagebuch-Code. Ein Tagebuch-Code beginnt mit !EUJ1! (EldoUI) oder FJ1: (Forever Journal).",
	["That is not a runs code. A runs code starts with !EUJR1!."] = "Das ist kein Durchlaufcode. Ein Durchlaufcode beginnt mit !EUJR1!.",
	["That is one of your goals already."] = "Das ist bereits eines Eurer Ziele.",
	["That item does not go in an equipment slot."] = "Dieser Gegenstand gehört in keinen Ausrüstungsplatz.",
	["That item does not go in this slot."] = "Dieser Gegenstand gehört nicht in diesen Platz.",
	["That quest chain is not in the quest data."] = "Diese Questreihe ist nicht in den Questdaten.",
	["The %s page is switched off on the Loot Guide settings page."] = "Die Seite %s ist auf der Einstellungsseite des Loot Guide ausgeschaltet.",
	["The Alts module stays off while %s is loaded, so only this character is known."] = "Das Modul Charaktere bleibt aus, solange %s geladen ist, daher ist nur dieser Charakter bekannt.",
	["The Argent Dawn sends you to Naxxramas once you are Honored or better; each rank makes the way in cheaper."] = "Die Argentumdämmerung schickt Euch nach Naxxramas, sobald Ihr Wohlwollend oder besser seid; jeder Rang macht den Weg hinein billiger.",
	["The Attunements tab lives in the Loot Guide. Turn the Loot Guide on first."] = "Der Reiter Einstimmungen gehört zum Loot Guide. Schaltet zuerst den Loot Guide ein.",
	["The Attunements tab lives in the Loot Guide. Turn the Loot Guide on to use it."] = "Der Reiter Einstimmungen gehört zum Loot Guide. Schaltet den Loot Guide ein, um ihn zu nutzen.",
	["The Crescent Key opens the doors of Dire Maul West and North; a boss in Dire Maul East drops it."] = "Der Mondsichelschlüssel öffnet die Türen von Düsterbruch West und Nord; ein Boss in Düsterbruch Ost lässt ihn fallen.",
	["The Defilers"] = "Die Entweihten",
	["The Drowned City"] = "The Drowned City",
	["The EldoUI page and the place to report problems. Copy (Ctrl+C) and open them in your browser."] = "Die Seite von EldoUI und der Ort, um Probleme zu melden. Kopiert (Strg+C) und öffnet sie in Eurem Browser.",
	["The EldoUI project page and the address to report a wrong drop or a problem, ready to copy."] = "Die Projektseite von EldoUI und die Adresse, um eine falsche Beute oder ein Problem zu melden, bereit zum Kopieren.",
	["The Exodar"] = "Die Exodar",
	["The Hall of Thanes"] = "The Hall of Thanes",
	["The Journal window's dark page and the EldoUI Book, the Storyteller detail with keepsakes, the tracker under your quests and moments in the alert lane."] = "Die dunkle Seite des Tagebuchfensters und das EldoUI-Buch, das Erzähler-Detail mit Andenken, der Tracker unter Euren Quests und Momente in der Warnspalte.",
	["The Journal window's own dark page with the accent color."] = "Die eigene dunkle Seite des Tagebuchfensters mit der Akzentfarbe.",
	["The Journey's day view on the day you last played."] = "Die Tagesansicht der Reise am Tag, an dem Ihr zuletzt gespielt habt.",
	["The Key to the City opens the service gate of Stratholme; a boss inside drops it."] = "Der Schlüssel zur Stadt öffnet das Diensttor von Stratholme; ein Boss darin lässt ihn fallen.",
	["The League of Arathor"] = "Der Bund von Arathor",
	["The Loot Guide opens out of combat."] = "Der Loot Guide öffnet sich außerhalb des Kampfes.",
	["The Loot Guide stays off while %s is loaded."] = "Der Loot Guide bleibt aus, solange %s geladen ist.",
	["The Night ledger Book in smaller text, short chapters and a slim tracker. Row size stays the Loot Guide's own setting."] = "Das Buch Nachtbuch in kleinerem Text, kurze Kapitel und ein schmaler Tracker. Die Zeilengröße bleibt die eigene Einstellung des Loot Guide.",
	["The PvP planner works out weeks from this. Leave 0 to use what you earned in recent weeks."] = "Der PvP-Planer rechnet damit Wochen aus. Lasst 0 stehen, um zu nutzen, was Ihr in den letzten Wochen verdient habt.",
	["The Seal of Ascension opens the doors of Upper Blackrock Spire for your whole group."] = "Das Siegel des Aufstiegs öffnet die Türen der Oberen Schwarzfelsspitze für Eure ganze Gruppe.",
	["The Shadowforge Key opens the gates deeper in Blackrock Depths."] = "Der Schattenschmiedeschlüssel öffnet die Tore tiefer in den Schwarzfelstiefen.",
	["The Shapers Terrace"] = "The Shapers Terrace",
	["The Skeleton Key opens the gates of Scholomance."] = "Der Skelettschlüssel öffnet die Tore der Scholomance.",
	["The Warlord's Command chain through Blackrock Spire ends with the Drakefire Amulet you need for Onyxia's Lair."] = "Die Kette Befehl des Kriegsherrn durch die Schwarzfelsspitze endet mit dem Drachenfeueramulett, das Ihr für Onyxias Hort braucht.",
	["The Zones section lives in the Loot Guide. Turn the Loot Guide on to use it."] = "Der Bereich Gebiete gehört zum Loot Guide. Schaltet den Loot Guide ein, um ihn zu nutzen.",
	["The adventurer's log: plain past tense, places and levels first."] = "Das Logbuch des Abenteurers: schlichte Vergangenheit, Orte und Stufen zuerst.",
	["The backup is merged into your journal."] = "Die Sicherung wird mit Eurem Tagebuch zusammengeführt.",
	["The best gear you can get for your spec and level, your filter and stat order, and two plan sets of your own."] = "Die beste Ausrüstung, die Ihr für Spezialisierung und Stufe bekommen könnt, Euer Filter und Eure Wertereihenfolge und zwei eigene Plansets.",
	["The best idea for right now and why it is here. A dungeon opens as a trip plan: the quests to pick up first, getting in, inside, and afterwards. Every button only shows you the way."] = "Die beste Idee für jetzt und warum sie hier steht. Ein Dungeon öffnet sich als Reiseplan: die Quests vorher, der Weg hinein, drinnen und danach. Jeder Knopf zeigt Euch nur den Weg.",
	["The best item per slot from your list, what you wear, your two plan sets and your wishlist by slot. Click a slot to pick something else."] = "Der beste Gegenstand pro Platz aus Eurer Liste, was Ihr tragt, Eure zwei Plansets und Eure Wunschliste nach Platz. Klickt einen Platz, um etwas anderes zu wählen.",
	["The best items on your list for your spec and the plan phase, one per slot. The number is the gain over what you wear."] = "Die besten Gegenstände Eurer Liste für Eure Spezialisierung und die Planphase, einer pro Platz. Die Zahl ist der Gewinn gegenüber dem, was Ihr tragt.",
	["The card joins the suggestions again."] = "Die Karte kommt wieder zu den Vorschlägen.",
	["The cards you put away. They come back at your next level or after 24 hours."] = "Die weggelegten Karten. Sie kommen bei Eurer nächsten Stufe oder nach 24 Stunden zurück.",
	["The cards you sent off with Not now, with Bring back."] = "Die Karten, die Ihr mit Nicht jetzt weggeschickt habt, mit Zurückholen.",
	["The cards you sent off with Not now."] = "Die Karten, die Ihr mit Nicht jetzt weggeschickt habt.",
	["The chain as a chart: every step a box, lines to the steps that need it."] = "Die Kette als Diagramm: jeder Schritt ein Kasten, Linien zu den Schritten, die ihn brauchen.",
	["The check could not start."] = "Die Prüfung konnte nicht starten.",
	["The check is running: %d of %d quests asked. %s stops it."] = { one = "Die Prüfung läuft: %d von %d Quest abgefragt. %s stoppt sie.", other = "Die Prüfung läuft: %d von %d Quests abgefragt. %s stoppt sie." },
	["The client does not know where this entrance is."] = "Der Client weiß nicht, wo dieser Eingang ist.",
	["The code is incomplete or damaged (%s). Copy all of it and paste it again."] = "Der Code ist unvollständig oder beschädigt (%s). Kopiert ihn ganz und fügt ihn erneut ein.",
	["The code is incomplete or damaged. Copy all of it and paste it again."] = "Der Code ist unvollständig oder beschädigt. Kopiert ihn ganz und fügt ihn erneut ein.",
	["The code is incomplete or damaged. Copy all of it, from FJ1: to the last }."] = "Der Code ist unvollständig oder beschädigt. Kopiert ihn ganz, von FJ1: bis zur letzten }.",
	["The commands and the address for problems. Pages, drop chances, the rating mode, alerts and the window look are in /eui > Loot Guide."] = "Die Befehle und die Adresse für Probleme. Seiten, Beutechancen, Bewertungsmodus, Hinweise und das Aussehen des Fensters findet Ihr unter /eui > Loot Guide.",
	["The data has no place on your map for this quest's giver."] = "Die Daten haben keinen Ort auf Eurer Karte für den Questgeber dieser Quest.",
	["The database needs the loot data"] = "Die Datenbank braucht die Beutedaten",
	["The door opens at level %d."] = "Die Tür öffnet sich ab Stufe %d.",
	["The drop data comes with the Loot Guide. Turn the Loot Guide on to use it."] = "Die Beutedaten kommen mit dem Loot Guide. Schaltet den Loot Guide ein, um sie zu nutzen.",
	["The entrance is %s."] = "Der Eingang liegt %s.",
	["The export did not work. The error is in the error list."] = "Der Export hat nicht geklappt. Der Fehler steht in der Fehlerliste.",
	["The filters hide every answer."] = "Die Filter verbergen jede Antwort.",
	["The first faction that counts you as Honored."] = "Die erste Fraktion, die Euch als Wohlwollend ansieht.",
	["The first flight path you learned."] = "Die erste Flugroute, die Ihr gelernt habt.",
	["The first one on %s. Take its items or money from a mailbox."] = "Die erste läuft am %s ab. Holt ihre Gegenstände oder ihr Geld aus einem Briefkasten.",
	["The first page is still blank"] = "Die erste Seite ist noch leer",
	["The first quest you handed in with a group."] = "Die erste Quest, die Ihr in einer Gruppe abgegeben habt.",
	["The first rare you saw."] = "Der erste seltene Gegner, den Ihr gesehen habt.",
	["The first step is open: %s."] = "Der erste Schritt ist offen: %s.",
	["The first time you died. It happens to everyone."] = "Das erste Mal, als Ihr gestorben seid. Das passiert jedem.",
	["The first time you entered a dungeon."] = "Das erste Mal, als Ihr einen Dungeon betreten habt.",
	["The first time you entered a raid."] = "Das erste Mal, als Ihr einen Schlachtzug betreten habt.",
	["The game could not save it. Try your own screenshot key."] = "Das Spiel konnte ihn nicht speichern. Versucht Eure eigene Screenshot-Taste.",
	["The game did not show your weapon skill, so the simulator used the usual skill for your level (5 per level)."] = "Das Spiel hat Eure Waffenfertigkeit nicht angezeigt, daher nutzt der Simulator die übliche Fertigkeit für Eure Stufe (5 pro Stufe).",
	["The game does not list that faction for you yet. Check the spelling on your Reputation tab."] = "Das Spiel listet diese Fraktion für Euch noch nicht. Prüft die Schreibweise in Eurem Ruf-Reiter.",
	["The game does not list this dungeon yet. It shows here as soon as it does."] = "Das Spiel listet diesen Dungeon noch nicht. Er erscheint hier, sobald es das tut.",
	["The game does not report this step; it counts once the next one is done."] = "Das Spiel meldet diesen Schritt nicht; er zählt, sobald der nächste erledigt ist.",
	["The game does not tell where this entrance is."] = "Das Spiel sagt nicht, wo dieser Eingang ist.",
	["The game has no map picture for this place. Here are its bosses in order; click one for its loot."] = "Das Spiel hat kein Kartenbild für diesen Ort. Hier sind seine Bosse der Reihe nach; klickt einen für seine Beute an.",
	["The game has no name for that place yet."] = "Das Spiel hat für diesen Ort noch keinen Namen.",
	["The game has not sent this item's stats yet."] = "Das Spiel hat die Werte dieses Gegenstands noch nicht gesendet.",
	["The game remembers %s quests you finished before the journal began."] = { one = "Das Spiel weiß von %s Quest, die Ihr vor Beginn des Tagebuchs abgeschlossen habt.", other = "Das Spiel weiß von %s Quests, die Ihr vor Beginn des Tagebuchs abgeschlossen habt." },
	["The game shows this rare on your minimap right now."] = "Das Spiel zeigt diesen seltenen Gegner gerade auf Eurer Minikarte.",
	["The game's calendar is not available here, so no event shows as active."] = "Der Kalender des Spiels ist hier nicht verfügbar, daher wird kein Event als aktiv angezeigt.",
	["The game's map could not place any creature camp. Open the world map once and come back."] = "Die Karte des Spiels konnte kein Kreaturenlager platzieren. Öffnet einmal die Weltkarte und kommt zurück.",
	["The game's map says you are in this zone."] = "Laut Karte des Spiels seid Ihr in dieser Zone.",
	["The game's own count of quests you completed."] = "Die eigene Zählung des Spiels Eurer abgeschlossenen Quests.",
	["The game's own count of your deaths."] = "Die eigene Zählung des Spiels Eurer Tode.",
	["The gear you wear; each slot shows how much its Best in Slot item adds."] = "Die Ausrüstung, die Ihr tragt; jeder Platz zeigt, wie viel sein Best-in-Slot-Gegenstand bringt.",
	["The group finder could not open here."] = "Die Gruppensuche konnte sich hier nicht öffnen.",
	["The group finder opens after combat."] = "Die Gruppensuche öffnet sich nach dem Kampf.",
	["The guide goes back to following your zone when your map changes."] = "Der Guide folgt wieder Eurer Zone, wenn sich Eure Karte ändert.",
	["The guide needs the loot data (the EldoUI_LootData addon) or the game's dungeon finder list to suggest trips."] = "Der Guide braucht die Beutedaten (das Addon EldoUI_LootData) oder die Liste der Dungeonsuche des Spiels, um Reisen vorzuschlagen.",
	["The guide needs the loot data (the EldoUI_LootData addon) or the game's dungeon finder list to suggest trips. Quests in your log still show here."] = "Der Guide braucht die Beutedaten (das Addon EldoUI_LootData) oder die Liste der Dungeonsuche des Spiels, um Reisen vorzuschlagen. Quests in Eurem Log erscheinen trotzdem hier.",
	["The honor cost and PvP rank the item needs."] = "Die Ehrenkosten und der PvP-Rang, die der Gegenstand braucht.",
	["The import is undone."] = "Der Import ist rückgängig gemacht.",
	["The instance page with every boss, its quests and its trash loot."] = "Die Instanzseite mit jedem Boss, ihren Quests und ihrer Trash-Beute.",
	["The item; its color is its quality."] = "Der Gegenstand; seine Farbe ist seine Qualität.",
	["The items you see this boss drop are added here."] = "Gegenstände, die Ihr diesen Boss fallen seht, kommen hier hinzu.",
	["The journal as a readable document, by chapter, with goals, notes and quests. Companion names are left out."] = "Das Tagebuch als lesbares Dokument, nach Kapiteln, mit Zielen, Notizen und Quests. Namen von Gefährten werden weggelassen.",
	["The journal as a web page (HTML). Save it as a .html file, open it in a browser and print it to PDF. Opened outside the game it loads its fonts from Google Fonts."] = "Das Tagebuch als Webseite (HTML). Speichert es als .html-Datei, öffnet es in einem Browser und druckt es als PDF. Außerhalb des Spiels geöffnet lädt es seine Schriften von Google Fonts.",
	["The journal as plain text, by chapter."] = "Das Tagebuch als reiner Text, nach Kapiteln.",
	["The journal begins in %s"] = "Das Tagebuch beginnt in %s",
	["The journal has no company by that name."] = "Das Tagebuch kennt keine Begleitung dieses Namens.",
	["The journal has not been here yet."] = "Das Tagebuch war noch nicht hier.",
	["The journal is not ready yet. Try again in a moment."] = "Das Tagebuch ist noch nicht bereit. Versucht es gleich noch einmal.",
	["The journal of %s, saved %s."] = "Das Tagebuch von %s, gespeichert %s.",
	["The journal shows what the game and your other EldoUI modules wrote down. Nothing is guessed."] = "Das Tagebuch zeigt, was das Spiel und Eure anderen EldoUI-Module aufgeschrieben haben. Nichts wird geraten.",
	["The journal waits for the end of combat"] = "Das Tagebuch wartet auf das Ende des Kampfes",
	["The journal's own rows: short, exact, with digits."] = "Die eigenen Zeilen des Tagebuchs: kurz, genau, mit Ziffern.",
	["The journal's pages are switched off or still loading."] = "Die Seiten des Tagebuchs sind ausgeschaltet oder laden noch.",
	["The last one you had open"] = "Die zuletzt geöffnete",
	["The last run is outdated: your level, gear, talents or list changed."] = "Der letzte Lauf ist veraltet: Eure Stufe, Ausrüstung, Talente oder Liste haben sich geändert.",
	["The level log was off for these levels."] = "Das Stufenprotokoll war für diese Stufen aus.",
	["The level of the target dummy. Bosses are three levels above you: more misses, glancing blows and resists."] = "Die Stufe der Trainingsattrappe. Bosse sind drei Stufen über Euch: mehr Fehlschläge, gestreifte Schläge und Widerstände.",
	["The light part is rested experience: kills give double experience until it is used up."] = "Der helle Teil ist Erholungserfahrung: Siege bringen doppelte Erfahrung, bis sie aufgebraucht ist.",
	["The line is in the chat box. Press Enter to send it, or Escape to drop it."] = "Die Zeile steht im Chatfeld. Drückt die Eingabetaste, um sie zu senden, oder Esc, um sie zu verwerfen.",
	["The list on the left leaves out attunements you have finished."] = "Die Liste links lässt abgeschlossene Einstimmungen weg.",
	["The long chain of Anachronos and the three dragonflights that opens the gates of Ahn'Qiraj."] = "Die lange Kette von Anachronos und den drei Drachenschwärmen, die die Tore von Ahn'Qiraj öffnet.",
	["The long chain through Stormwind and Blackrock Spire ends with the Drakefire Amulet you need for Onyxia's Lair."] = "Die lange Kette durch Stormwind und die Schwarzfelsspitze endet mit dem Drachenfeueramulett, das Ihr für Onyxias Hort braucht.",
	["The loot data does not list where this recipe comes from."] = "Die Beutedaten nennen nicht, woher dieses Rezept stammt.",
	["The loot data has no place on your map for this."] = "Die Beutedaten haben dafür keinen Ort auf Eurer Karte.",
	["The loot data has no rares or named creatures for the zone you are in. Pick a zone on the left."] = "Die Beutedaten haben keine seltenen oder benannten Kreaturen für Eure Zone. Wählt links eine Zone.",
	["The loot data lists no bosses here."] = "Die Beutedaten listen hier keine Bosse.",
	["The loot data lists no crafts for this profession."] = "Die Beutedaten listen für diesen Beruf keine Rezepte.",
	["The loot data lists no factions for your side."] = "Die Beutedaten listen keine Fraktionen für Eure Seite.",
	["The loot data lists no factions of the other side."] = "Die Beutedaten listen keine Fraktionen der anderen Seite.",
	["The loot data lists no rewards for this faction."] = "Die Beutedaten listen für diese Fraktion keine Belohnungen.",
	["The loot data lists no vendors, quest rewards or drops for this event."] = "Die Beutedaten listen für dieses Ereignis keine Händler, Questbelohnungen oder Beute.",
	["The lowest quality a find needs to be written on the Journey. Changing it on a preset turns it into Custom."] = "Die niedrigste Qualität, die ein Fund braucht, um auf der Reise notiert zu werden. Eine Änderung an einer Vorgabe macht sie zu Benutzerdefiniert.",
	["The mouse wheel turns the pages too."] = "Auch das Mausrad blättert die Seiten um.",
	["The name leaves every run and your companions; the runs and everyone else stay. Undo brings it back for 7 days."] = "Der Name verschwindet aus jedem Durchlauf und aus Euren Gefährten; die Durchläufe und alle anderen bleiben. Rückgängig holt ihn 7 Tage lang zurück.",
	["The next open step of each attunement and key."] = "Der nächste offene Schritt jeder Einstimmung und jedes Schlüssels.",
	["The next part of the tour."] = "Der nächste Teil der Tour.",
	["The next step's quest giver on the map and toasts as you go."] = "Der Questgeber des nächsten Schritts auf der Karte und Einblendungen unterwegs.",
	["The numbers come from many short fights with random rolls. The ± range shows how sure they are (95 %)."] = "Die Zahlen stammen aus vielen kurzen Kämpfen mit Zufallswürfen. Der ±-Bereich zeigt, wie sicher sie sind (95 %).",
	["The oldest %d are kept as counts on their levels."] = { one = "Der älteste %d bleibt als Zahl auf seiner Stufe.", other = "Die ältesten %d bleiben als Zahlen auf ihren Stufen." },
	["The oldest goes when a new one would pass this. The newest copy from before an EldoUI update has a slot of its own and is always kept."] = "Der älteste fällt weg, wenn ein neuer dies überschreiten würde. Die neueste Kopie von vor einem EldoUI-Update hat einen eigenen Platz und bleibt immer erhalten.",
	["The order your spec values stats in. Drag to change it."] = "Die Reihenfolge, in der Eure Spezialisierung Werte gewichtet. Zieht, um sie zu ändern.",
	["The page the window shows when you open it outside a dungeon. The gear holds a switch for each page and the Catalog's settings."] = "Die Seite, die das Fenster zeigt, wenn Ihr es außerhalb eines Dungeons öffnet. Das Zahnrad enthält einen Schalter für jede Seite und die Einstellungen des Katalogs.",
	["The pages of My Adventure on the Journal window's own dark panel, or on parchment with dark ink. The Book and the character card keep their own Book look."] = "Die Seiten von Mein Abenteuer auf der eigenen dunklen Fläche des Tagebuchfensters oder auf Pergament mit dunkler Tinte. Das Buch und die Charakterkarte behalten ihr eigenes Buch-Aussehen.",
	["The part before."] = "Der vorherige Teil.",
	["The people you grouped with last first."] = "Die Leute, mit denen Ihr zuletzt gruppiert wart, zuerst.",
	["The people you met and grouped with."] = "Die Leute, die Ihr getroffen habt und mit denen Ihr gruppiert wart.",
	["The people you spent the most time with first."] = "Die Leute, mit denen Ihr die meiste Zeit verbracht habt, zuerst.",
	["The people you traveled with: time together and how it was spent, dungeons and quests together, and your notes on them."] = "Die Leute, mit denen Ihr gereist seid: gemeinsame Zeit und wie sie verbracht wurde, gemeinsame Dungeons und Quests und Eure Notizen über sie.",
	["The places you came to last first."] = "Die Orte, an die Ihr zuletzt kamt, zuerst.",
	["The places you spent the most time in first."] = "Die Orte, an denen Ihr die meiste Zeit verbracht habt, zuerst.",
	["The planner is already empty."] = "Der Planer ist schon leer.",
	["The planner is empty."] = "Der Planer ist jetzt leer.",
	["The quest chains come from EldoUI_LootData, which loads a few seconds after login."] = "Die Questreihen stammen aus EldoUI_LootData, das ein paar Sekunden nach dem Einloggen lädt.",
	["The quest giver is %s."] = "Der Questgeber ist %s.",
	["The quest giver's exclamation mark right of the bar, like the game's quest icon."] = "Das Ausrufezeichen des Questgebers rechts vom Balken, wie das Questsymbol des Spiels.",
	["The quest givers are %s."] = "Die Questgeber sind %s.",
	["The quest tracker leaves room at its bottom for the journal tracker. With Questie, the journal tracker sits right under Questie's list."] = "Der Questtracker lässt unten Platz für den Tagebuch-Tracker. Mit Questie sitzt der Tagebuch-Tracker direkt unter der Liste von Questie.",
	["The quests for this instance with your status: open, done or locked."] = "Die Quests dieser Instanz mit Eurem Stand: offen, erledigt oder gesperrt.",
	["The quests you archived, with Restore."] = "Die Quests, die Ihr archiviert habt, mit Wiederherstellen.",
	["The reminder stays and shows each time, instead of once."] = "Die Erinnerung bleibt und erscheint jedes Mal statt nur einmal.",
	["The reputation the item needs, red while you are below it."] = "Der Ruf, den der Gegenstand braucht, rot, solange Ihr darunter seid.",
	["The rewards list couldn't load."] = "Die Belohnungsliste konnte nicht geladen werden.",
	["The road is waiting. Every zone you visit gets a card."] = "Der Weg wartet. Jede Zone, die Ihr besucht, bekommt eine Karte.",
	["The role they had when they sent it."] = "Die Rolle, die sie beim Senden hatten.",
	["The run leaves your journal; everything else stays. Undo brings it back for 7 days."] = "Der Durchlauf verschwindet aus Eurem Tagebuch; alles andere bleibt. Rückgängig holt ihn 7 Tage lang zurück.",
	["The runs of %s, saved %s."] = "Die Durchläufe von %s, gespeichert %s.",
	["The same fights (same dice) for every set, so the differences are steadier than the totals."] = "Für jedes Set dieselben Kämpfe (dieselben Würfel), daher sind die Unterschiede stabiler als die Summen.",
	["The search index is built out of combat. Try again in a moment."] = "Der Suchindex wird außerhalb des Kampfes aufgebaut. Versucht es gleich noch einmal.",
	["The search looks through the %s table."] = "Die Suche durchsucht die Tabelle %s.",
	["The section My Adventure opens on: Today, a page you pick (Next trips, Journey, Book, Story so far, Keepsakes, Places, Quests, Fellowship, Goals or Notes), or the last one you had open."] = "Der Abschnitt, mit dem Mein Abenteuer öffnet: Heute, eine Seite Eurer Wahl (Nächste Reisen, Reise, Buch, Die Geschichte bisher, Andenken, Orte, Quests, Gefährten, Ziele oder Notizen) oder die zuletzt geöffnete.",
	["The section you came back from. Alt+Right does the same."] = "Der Abschnitt, aus dem Ihr zurückkamt. Alt+Rechts tut dasselbe.",
	["The section you had open before. Alt+Left or Backspace does the same."] = "Der Abschnitt, den Ihr vorher offen hattet. Alt+Links oder Rücktaste tut dasselbe.",
	["The set an item is part of (owned of total) and what a token buys."] = "Das Set, zu dem ein Gegenstand gehört (Besitz von gesamt), und was eine Marke kauft.",
	["The set bonuses show once the game has the pieces' details (hover a piece once)."] = "Die Setboni erscheinen, sobald das Spiel die Details der Teile hat (fahrt einmal über ein Teil).",
	["The set is shared with the Best in Slot page. This can't be undone."] = "Das Set wird mit der Best-in-Slot-Seite geteilt. Dies kann nicht rückgängig gemacht werden.",
	["The simulation is done."] = "Die Simulation ist fertig.",
	["The simulator could not start."] = "Der Simulator konnte nicht starten.",
	["The simulator folder EldoUI_LootSim is not installed. It comes with EldoUI: put it next to the EldoUI folder in Interface\\AddOns."] = "Der Simulatorordner EldoUI_LootSim ist nicht installiert. Er gehört zu EldoUI: Legt ihn neben den Ordner EldoUI in Interface\\AddOns.",
	["The simulator found no damage spells it can use yet."] = "Der Simulator hat noch keine Schadenszauber gefunden, die er nutzen kann.",
	["The simulator has no model for your class."] = "Der Simulator hat kein Modell für Eure Klasse.",
	["The simulator has no numbers for this item yet."] = "Der Simulator hat für diesen Gegenstand noch keine Werte.",
	["The simulator has no stats for these items, so sets with them are not simulated: "] = "Der Simulator hat keine Werte für diese Gegenstände, daher werden Sets mit ihnen nicht simuliert: ",
	["The simulator runs out of combat. Try again when the fight is over."] = "Der Simulator läuft außerhalb des Kampfes. Versucht es nach dem Kampf erneut.",
	["The sound that plays with a wishlist alert."] = "Der Klang, der mit einem Wunschlisten-Hinweis spielt.",
	["The step is %s."] = "Der Schritt ist %s.",
	["The step is ready to hand in."] = "Der Schritt ist bereit zur Abgabe.",
	["The suggestions again."] = "Wieder die Vorschläge.",
	["The tab lists attunements, keys and dungeon quests once the quest data is loaded."] = "Der Reiter listet Einstimmungen, Schlüssel und Dungeonquests, sobald die Questdaten geladen sind.",
	["The tavern song: warm and vivid, never false."] = "Das Tavernenlied: warm und lebendig, nie falsch.",
	["The tooltip line has its own switch on the Tooltip page. The chance follows the Loot Guide's Drop chances setting."] = "Die Tooltipzeile hat einen eigenen Schalter auf der Seite Tooltip. Die Chance folgt der Einstellung Beutechancen des Loot Guide.",
	["The tour runs out of combat."] = "Die Tour läuft außerhalb des Kampfes.",
	["The view the Overview button opens first."] = "Die Ansicht, die der Knopf Übersicht zuerst öffnet.",
	["The whole Book in this tone as plain text, in a copy box."] = "Das ganze Buch in diesem Ton als reiner Text, in einem Kopierfeld.",
	["The whole journal as one code, to keep or to paste in on another PC. Nothing is sent anywhere."] = "Das ganze Tagebuch als ein Code, zum Aufbewahren oder zum Einfügen auf einem anderen PC. Nichts wird irgendwohin gesendet.",
	["The whole story in this tone as plain text, in a copy box."] = "Die ganze Geschichte in diesem Ton als reiner Text, in einem Kopierfeld.",
	["The whole story with headings, for a website, a forum, or Discord."] = "Die ganze Geschichte mit Überschriften, für eine Webseite, ein Forum oder Discord.",
	["The window lets the game show through a little. How much: General > Panel opacity. Drag the window's corner grip to change its size."] = "Das Fenster lässt das Spiel ein wenig durchscheinen. Wie stark: General > Panel opacity. Zieht am Eckgriff des Fensters, um seine Größe zu ändern.",
	["The zone is %d-%d; you are level %d."] = "Die Zone ist %d-%d; Ihr seid Stufe %d.",
	["The zone list is built out of combat. It shows once the fight is over."] = "Die Gebietsliste wird außerhalb des Kampfes erstellt. Sie erscheint, sobald der Kampf vorbei ist.",
	["Theramore Expeditionary Force"] = "Theramore Expeditionary Force",
	["There are no runs to back up yet."] = "Es gibt noch keine Durchläufe zum Sichern.",
	["There is no import to undo."] = "Es gibt keinen Import zum Rückgängigmachen.",
	["There is no journal to back up yet."] = "Es gibt noch kein Tagebuch zum Sichern.",
	["There is no journal to export yet."] = "Es gibt noch kein Tagebuch zum Exportieren.",
	["There is no live position inside dungeons."] = "In Dungeons gibt es keine Live-Position.",
	["They come back at your next level or after 24 hours."] = "Sie kommen bei Eurer nächsten Stufe oder nach 24 Stunden zurück.",
	["They may be in another character's fellowship."] = "Vielleicht sind sie in der Gefährtenschaft eines anderen Charakters.",
	["They were level %s."] = "Sie waren Stufe %s.",
	["Things you want to work towards. Their progress moves by itself as the game reports it."] = "Dinge, auf die Ihr hinarbeiten wollt. Ihr Fortschritt bewegt sich von selbst, wie das Spiel ihn meldet.",
	["This backup is still being written. Try again in a moment."] = "Diese Sicherung wird noch geschrieben. Versuche es gleich noch einmal.",
	["This can be done out of combat only."] = "Während eines Kampfes ist das nicht möglich!",
	["This client"] = "Dieser Client",
	["This client cannot set a map pin."] = "Dieser Client kann keine Kartenmarkierung setzen.",
	["This client has no group finder window."] = "Dieser Client hat kein Gruppensuche-Fenster.",
	["This game client cannot answer quest questions."] = "Dieser Spielclient kann keine Questfragen beantworten.",
	["This game client does not tell add-ons about poisons, oils and other temporary weapon enchants, so they are not counted."] = "Dieser Spielclient teilt Addons Gifte, Öle und andere vorübergehende Waffenverzauberungen nicht mit, daher werden sie nicht gezählt.",
	["This is how wishlist alerts look."] = "So sehen Wunschlisten-Hinweise aus.",
	["This list is already empty."] = "Diese Liste ist schon leer.",
	["This list shows the factions you have met. Show all factions to see every faction's rewards."] = "Diese Liste zeigt die Fraktionen, denen Ihr begegnet seid. Alle Fraktionen zeigen zeigt die Belohnungen jeder Fraktion.",
	["This page shows where to go next and what is waiting for you."] = "Diese Seite zeigt, wohin es als Nächstes geht und was auf Euch wartet.",
	["This place cannot be shown on your map."] = "Dieser Ort kann nicht auf Eurer Karte gezeigt werden.",
	["This place has no dungeon map."] = "Dieser Ort hat keine Dungeonkarte.",
	["This place has no point on your map yet."] = "Dieser Ort hat noch keinen Punkt auf Eurer Karte.",
	["Thorium Brotherhood"] = "Thoriumbruderschaft",
	["Thunder Bluff"] = "Donnerfels",
	["Tier sets"] = "Tier-Sets",
	["Timbermaw Hold"] = "Holzschlundfeste",
	["Time here"] = "Zeit hier",
	["Time in the same group, away from keyboard not counted."] = "Zeit in derselben Gruppe, Abwesenheit nicht mitgezählt.",
	["Time played at each level, from the level log."] = "Gespielte Zeit auf jeder Stufe, aus dem Stufenprotokoll.",
	["Time together"] = "Gemeinsame Zeit",
	["Time you spent here, away from keyboard not counted."] = "Die Zeit, die Ihr hier verbracht habt, Abwesenheit nicht mitgezählt.",
	["To level"] = "Bis Stufe",
	["Toast (Alerts and Banners)"] = "Toast (Alerts and Banners)",
	["Toast, else loot toast, else chat"] = "Toast, sonst Beute-Toast, sonst Chat",
	["Today"] = "Heute",
	["Together"] = "Gemeinsam",
	["Tokens"] = "Marken",
	["Tokens come from EldoUI_LootData. Install it next to EldoUI to list them."] = "Marken kommen aus EldoUI_LootData. Installiert es neben EldoUI, um sie aufzulisten.",
	["Tokens shows what each raid token buys for a class."] = "Marken zeigt, was jede Schlachtzugsmarke für eine Klasse kauft.",
	["Tone"] = "Tonfall",
	["Too low level"] = "Stufe zu niedrig",
	["Tooltip line settings"] = "Einstellungen der Tooltipzeilen",
	["Tooltip: %s"] = "Tooltip: %s",
	["Tooltips and map"] = "Tooltips und Karte",
	["Total: %s %s"] = "Gesamt: %s %s",
	["Tour %d/%d"] = "Tour %d/%d",
	["Track"] = "Verfolgen",
	["Tracker and buttons"] = "Tracker und Schaltflächen",
	["Tracker height"] = "Trackerhöhe",
	["Tracks whether you have the Dalaran Sewer Key. One key holder can open the gate for the group; you do not need to finish the dungeon quest first."] = "Zeigt, ob Ihr den Schlüssel zur Kanalisation von Dalaran besitzt. Ein Schlüsselträger kann das Tor für die Gruppe öffnen; die Dungeonquest muss dafür noch nicht abgeschlossen sein.",
	["Trainer: %s %d"] = "Lehrer: %s %d",
	["Trash and zone drops"] = "Trash- und Gebietsbeute",
	["Traveling"] = "Unterwegs",
	["Trinket"] = "Schmuck",
	["Try again"] = "Erneut versuchen",
	["Try on"] = "Anprobieren",
	["Try on set"] = "Set anprobieren",
	["Turbo (16 ms a frame)"] = "Turbo (16 ms pro Bild)",
	["Turn Forever Journal off in the AddOns list and reload, so the two journals do not both write."] = "Schaltet Forever Journal in der AddOn-Liste aus und ladet neu, damit nicht beide Tagebücher schreiben.",
	["Turn in: %s"] = "Abgeben: %s",
	["Turn it on"] = "Einschalten",
	["Turn on Alts"] = "Charaktere einschalten",
	["Turn on Attunements to set this goal."] = "Schaltet Einstimmungen ein, um dieses Ziel zu setzen.",
	["Turn on Blizzard UI > Objective / quest tracker > Move and scale to keep the quest list clear of the journal tracker."] = "Schaltet Blizzard UI > Objective / quest tracker > Move and scale ein, damit die Questliste nicht unter dem Tagebuch-Tracker liegt.",
	["Turn on sharing"] = "Teilen einschalten",
	["Turn on sharing to ask guild and group members who use EldoUI for their attunements and to send yours. Nothing is sent until you click Ask or Send mine."] = "Schaltet Teilen ein, um Gilden- und Gruppenmitglieder mit EldoUI nach ihren Einstimmungen zu fragen und Eure zu senden. Nichts wird gesendet, bevor Ihr auf Fragen oder Meine senden klickt.",
	["Turn on the Alts module to see the attunements of your other characters here."] = "Schaltet das Modul Charaktere ein, um hier die Einstimmungen Eurer anderen Charaktere zu sehen.",
	["Turn on the Loot Guide"] = "Loot Guide einschalten",
	["Turn on the Nameplates module first."] = "Schaltet zuerst das Modul Nameplates ein.",
	["Turn-in"] = "Abgabe",
	["Turns Hide finished off."] = "Schaltet Erledigte ausblenden aus.",
	["Turns off My level only."] = "Schaltet Nur meine Stufe aus.",
	["Turns on Share with guild and group (Attunements settings)."] = "Schaltet Mit Gilde und Gruppe teilen ein (Einstellungen der Einstimmungen).",
	["Turns the filters off."] = "Schaltet die Filter aus.",
	["Turtle"] = "Schildkröte",
	["Two quick choices for this character. Both can be changed later."] = "Zwei schnelle Entscheidungen für diesen Charakter. Beide lassen sich später ändern.",
	["Two-hand"] = "Zweihändig",
	["Two-hander in the main hand"] = "Zweihänder in der Waffenhand",
	["Type %s in chat for the My Adventure settings."] = "Gib %s im Chat ein, um die Einstellungen von Mein Abenteuer zu öffnen.",
	["Type a little more"] = "Gebt etwas mehr ein",
	["Type the creature's name, or use your target."] = "Gebt den Namen der Kreatur ein oder nutzt Euer Ziel.",
	["Type the dungeon's name, for example The Deadmines."] = "Gebt den Namen des Dungeons ein, zum Beispiel Die Todesminen.",
	["Type the faction's name, for example Stormwind."] = "Gebt den Namen der Fraktion ein, zum Beispiel Stormwind.",
	["Type the place's name, for example Stranglethorn Vale or Frostmane Hold."] = "Gebt den Namen des Ortes ein, zum Beispiel Schlingendorntal.",
	["Type the profession's name, for example First Aid."] = "Gebt den Namen des Berufs ein, zum Beispiel Erste Hilfe.",
	["Type three letters in the box at the top (or an alias such as dm or zf) and press Enter."] = "Gebt drei Buchstaben in das Feld oben ein (oder ein Kürzel wie dm oder zf) und drückt die Eingabetaste.",
	["Undercity"] = "Unterstadt",
	["Undo the import"] = "Import rückgängig machen",
	["Unkeep"] = "Nicht mehr aufheben",
	["Unknown export format."] = "Unbekanntes Exportformat.",
	["Unknown goal type."] = "Unbekannte Zielart.",
	["Unpin"] = "Lösen",
	["Up/Down to pick, Enter to open"] = "Hoch/Runter zum Auswählen, Eingabe zum Öffnen",
	["Updating the list of runs. It fills in by itself in a moment."] = "Die Liste der Durchläufe wird aktualisiert. Sie füllt sich gleich von selbst.",
	["Upgrade for %s by %s"] = "Verbesserung für %s um %s",
	["Upgrade for %s, beats your %s by %s"] = "Verbesserung für %s, schlägt Euer %s um %s",
	["Upgrade for %s: nothing is worn in that slot"] = "Verbesserung für %s: In diesem Platz wird nichts getragen",
	["Upgrade: %s"] = "Verbesserung: %s",
	["Upgrade: %s."] = "Verbesserung: %s.",
	["Upgrades follow your stat weights. Choose Simulator under Rate items by to rate items with these fights."] = "Verbesserungen folgen Euren Wertgewichtungen. Wählt Simulator unter Gegenstände bewerten nach, um Gegenstände mit diesen Kämpfen zu bewerten.",
	["Upgrades for you"] = "Verbesserungen für Euch",
	["Upgrades for you that drop there."] = "Verbesserungen für Euch, die dort fallen.",
	["Upgrades only"] = "Nur Verbesserungen",
	["Upgrades only and Usable by me narrow the rewards; the side toggle shows the other faction's."] = "Nur Verbesserungen und Für mich nutzbar grenzen die Belohnungen ein; der Seitenschalter zeigt die der anderen Fraktion.",
	["Upgrades only hides creatures with nothing for you. Map on a rare card pins its camps, one per click."] = "Nur Verbesserungen blendet Kreaturen aus, die nichts für Euch haben. Karte auf einer Rarkarte markiert ihre Lager, eines pro Klick.",
	["Usable"] = "Nutzbar",
	["Usable by me"] = "Für mich nutzbar",
	["Usage: /eui wishlist add <item link>"] = "Verwendung: /eui wishlist add <Gegenstandslink>",
	["Use %d x %s"] = "%d x %s benutzen",
	["Use the Characters and Instances records"] = "Aufzeichnungen von Charakteren und Instanzen nutzen",
	["Use the simulator"] = "Simulator nutzen",
	["Vendor prices you saw: %d items"] = { one = "Gesehene Händlerpreise: %d Gegenstand", other = "Gesehene Händlerpreise: %d Gegenstände" },
	["Vendors"] = "Händler",
	["Vendors that sell the item, where they stand and what it costs."] = "Händler, die den Gegenstand verkaufen, wo sie stehen und was er kostet.",
	["Vendors: %d · crafts: %d · tokens: %d · world events: %d"] = "Händler: %d · Herstellung: %d · Marken: %d · Weltereignisse: %d",
	["Verdict"] = "Urteil",
	["Victories"] = "Siege",
	["Visit %s"] = "%s besuchen",
	["Visit a place"] = "Einen Ort besuchen",
	["Visited before the journal kept dates"] = "Besucht, bevor das Tagebuch Daten festhielt",
	["Waist"] = "Taille",
	["Waiting for you"] = "Wartet auf Euch",
	["Waiting to remind you"] = "Wartet darauf, Euch zu erinnern",
	["Waiting: addon messages are paused here"] = "Wartet: Addon-Nachrichten sind hier pausiert",
	["Walks through every page of the Loot Guide again, and shows the small tours of the filter, dungeon map and simulator again too."] = "Führt noch einmal durch jede Seite des Loot Guide und zeigt auch die kleinen Touren zu Filter, Dungeonkarte und Simulator wieder.",
	["Warsong Gulch"] = "Kriegshymnenschlucht",
	["Warsong Outriders"] = "Vorhut des Kriegshymnenklans",
	["Watched a cinematic"] = "Eine Zwischensequenz angesehen",
	["Wears the set on show. Drag to turn it, mouse wheel to zoom."] = "Trägt das gezeigte Set. Ziehen zum Drehen, Mausrad zum Zoomen.",
	["Welcome card put away."] = "Willkommenskarte weggelegt.",
	["Welcome to the Loot Guide"] = "Willkommen im Loot Guide",
	["Well rested"] = "Gut ausgeruht",
	["Well rested (%d%% of a level): a good time for a dungeon."] = "Gut ausgeruht (%d%% einer Stufe): eine gute Zeit für einen Dungeon.",
	["Well rested sound"] = "Ton für Gut ausgeruht",
	["What I wear"] = "Was ich trage",
	["What counts as open on WoW: Forever. Auto follows the announced days; pick a step if the game opens it earlier or later."] = "Was auf WoW: Forever als geöffnet gilt. Autom. folgt den angekündigten Tagen; wählt einen Schritt, wenn das Spiel ihn früher oder später öffnet.",
	["What do you want to do?"] = "Was möchtet Ihr tun?",
	["What each faction sells or gives at every standing, how far you are from it and which rewards are upgrades for you."] = "Was jede Fraktion auf jedem Rang verkauft oder gibt, wie weit Ihr davon entfernt seid und welche Belohnungen Verbesserungen für Euch sind.",
	["What each raid token or turn-in item buys for a class."] = "Was jede Schlachtzugsmarke oder jeder Abgabegegenstand für eine Klasse kauft.",
	["What happened here"] = "Was hier geschah",
	["What is ahead"] = "Was vor Euch liegt",
	["What is left are raids, attunements, and reputation. Next trips shows them once you turn on raids, and the Attunements page has every key."] = "Übrig sind Schlachtzüge, Einstimmungen und Ruf. Nächste Reisen zeigt sie, sobald Ihr Schlachtzüge einschaltet, und die Seite Einstimmungen hat jeden Schlüssel.",
	["What is left are raids, attunements, and reputation. Nothing else fits right now; put-away cards come back after 24 hours."] = "Übrig sind Schlachtzüge, Einstimmungen und Ruf. Sonst passt gerade nichts; weggelegte Karten kommen nach 24 Stunden zurück.",
	["What opens at level %d"] = "Was sich auf Stufe %d öffnet",
	["What opens at the next level"] = "Was sich auf der nächsten Stufe öffnet",
	["What shows"] = "Was erscheint",
	["What the game's quest lines report on this map. Copy it (Ctrl+C) and send it to EldoUI's authors."] = "Was die Questreihen des Spiels auf dieser Karte melden. Kopiert es (Strg+C) und sendet es an die Autoren von EldoUI.",
	["What the item adds over what you wear, with your stat priority."] = "Was der Gegenstand gegenüber Eurer Ausrüstung bringt, mit Eurer Wertepriorität.",
	["What the journal writes down, the look of its pages, and how the ideas are ranked. /eui tour journal shows this tour again."] = "Was das Tagebuch festhält, wie seine Seiten aussehen und wie die Ideen gereiht werden. /eui tour journal zeigt diese Tour erneut.",
	["What the journal wrote down since you last logged out."] = "Was das Tagebuch seit Eurem letzten Ausloggen festgehalten hat.",
	["What the pages show"] = "Was die Seiten zeigen",
	["What the pages show; everything is always written down. Essentials: levels, deaths, notes, goals. Storyteller: adds spells, professions and places. Chronicler: everything."] = "Was die Seiten zeigen; aufgeschrieben wird immer alles. Das Wichtigste: Stufen, Tode, Notizen, Ziele. Erzähler: dazu Zauber, Berufe und Orte. Chronist: alles.",
	["What the tab has loaded. Chains come from EldoUI_LootData (Classic values; WoW: Forever may differ)."] = "Was der Reiter geladen hat. Ketten kommen aus EldoUI_LootData (Classic-Werte; WoW: Forever kann abweichen).",
	["What was read"] = "Was gelesen wurde",
	["What would you like to work towards?"] = "Worauf möchtet Ihr hinarbeiten?",
	["What you wear, Best in Slot and your plan sets compared as DPS from the same fights."] = "Eure Ausrüstung, Best in Slot und Eure Plansets als DPS aus denselben Kämpfen verglichen.",
	["When a backup is taken by itself, 8 seconds after you log in and out of combat."] = "Wann eine Sicherung von selbst angelegt wird, 8 Sekunden nach dem Einloggen und außerhalb des Kampfes.",
	["When this note should show again as a reminder. It picks one from what you write until you choose yourself."] = "Wann diese Notiz als Erinnerung wieder erscheinen soll. Sie wählt eine aus dem, was Ihr schreibt, bis Ihr selbst wählt.",
	["When you apply a layout preset, the Book takes the look of the style that fits it: EldoUI, Storybook or Compact. What the journal shows is kept."] = "Wenn Ihr eine Layoutvorlage anwendet, übernimmt das Buch das Aussehen des passenden Stils: EldoUI, Bilderbuch oder Kompakt. Was das Tagebuch zeigt, bleibt erhalten.",
	["When you enter %s"] = "Wenn Ihr %s betretet",
	["When you open a profession"] = "Wenn Ihr einen Beruf öffnet",
	["When you reach level %d"] = "Wenn Ihr Stufe %d erreicht",
	["Where it began"] = "Wo es begann",
	["Where next"] = "Wohin als Nächstes",
	["Where recipes come from needs EldoUI_LootData. Install it next to EldoUI to see trainers, vendors, drops and quests."] = "Woher Rezepte kommen, braucht EldoUI_LootData. Installiert es neben EldoUI, um Lehrer, Händler, Beute und Quests zu sehen.",
	["Where the alert shows. Every alert also writes one chat line so you can read it later."] = "Wo der Hinweis erscheint. Jeder Hinweis schreibt auch eine Chatzeile, damit Ihr ihn später lesen könnt.",
	["Where the icon sits on the plate. Right of the bar comes after the elite and quest icons."] = "Wo das Symbol auf der Plakette sitzt. Rechts vom Balken kommt nach den Elite- und Questsymbolen.",
	["Where the item drops and how often, and the vendors that sell it with the cost. Hold Shift for more sources and the drops you saw yourself."] = "Wo der Gegenstand fällt und wie oft, und die Händler, die ihn verkaufen, mit dem Preis. Haltet Umschalt für mehr Quellen und die Beute, die Ihr selbst gesehen habt.",
	["Where this comes from"] = "Woher das kommt",
	["Where to go"] = "Wohin",
	["Where to go next and why: dungeons with their quests, quests that fit your level, attunement steps, and zones to explore."] = "Wohin als Nächstes und warum: Dungeons mit ihren Quests, Quests für Eure Stufe, Einstimmungsschritte und Gebiete zum Erkunden.",
	["Where to go next, what is waiting for you, and what just happened."] = "Wohin als Nächstes, was auf Euch wartet und was gerade geschah.",
	["Where to go now and what you get there: the best dungeon for your level, your next upgrades and your best-in-slot progress."] = "Wohin jetzt und was Ihr dort bekommt: der beste Dungeon für Eure Stufe, Eure nächsten Verbesserungen und Euer Best-in-Slot-Fortschritt.",
	["Where you left it"] = "Wo Ihr es gelassen habt",
	["Where you left off"] = "Wo Ihr aufgehört habt",
	["Which attunement?"] = "Welche Einstimmung?",
	["Which attunements the columns show."] = "Welche Einstimmungen die Spalten zeigen.",
	["Which classes the Class quests group lists."] = "Welche Klassen die Gruppe Klassenquests auflistet.",
	["Which creature?"] = "Welche Kreatur?",
	["Which dungeon?"] = "Welcher Dungeon?",
	["Which faction's steps the chain shows. Steps for both factions always show."] = "Die Schritte welcher Fraktion die Kette zeigt. Schritte für beide Fraktionen erscheinen immer.",
	["Which faction's steps the chains show (the same as the setting). Steps for both factions always show."] = "Die Schritte welcher Fraktion die Ketten zeigen (wie in der Einstellung). Schritte für beide Fraktionen erscheinen immer.",
	["Which faction?"] = "Welche Fraktion?",
	["Which item?"] = "Welcher Gegenstand?",
	["Which level?"] = "Welche Stufe?",
	["Which place?"] = "Welcher Ort?",
	["Which profession?"] = "Welcher Beruf?",
	["Which quest?"] = "Welche Quest?",
	["Which quests of each zone you have done and which are left, as a Catalog section of the Loot Guide, with the quest givers on the world map."] = "Welche Quests jedes Gebiets Ihr erledigt habt und welche offen sind, als Bereich im Katalog des Loot Guide, mit den Questgebern auf der Weltkarte.",
	["Which skill level?"] = "Welche Fertigkeitsstufe?",
	["Which standing?"] = "Welcher Rang?",
	["Who is attuned: your characters, or guild and group members who shared theirs."] = "Wer eingestimmt ist: Eure Charaktere oder Gilden- und Gruppenmitglieder, die ihre geteilt haben.",
	["Who you are and how far this level is. The light part of the bar is rested experience; the time to the next level counts only your own last levels."] = "Wer Ihr seid und wie weit diese Stufe ist. Der helle Teil der Leiste ist Erholungserfahrung; die Zeit bis zur nächsten Stufe zählt nur Eure eigenen letzten Stufen.",
	["Whose quests the list shows: yours, Alliance, Horde or both."] = "Wessen Quests die Liste zeigt: Eure, Allianz, Horde oder beide.",
	["Why"] = "Warum",
	["Why not higher?"] = "Warum nicht höher?",
	["Wind Serpent"] = "Windnatter",
	["Windfury"] = "Windzorn",
	["Windfury Weapon"] = "Waffe des Windzorns",
	["Window sounds"] = "Fenstertöne",
	["Wintersaber Trainers"] = "Wintersäblerausbilder",
	["Wish"] = "Wünschen",
	["Wish all missing"] = "Alle fehlenden wünschen",
	["Wish come true"] = "Wunsch erfüllt",
	["Wished"] = "Gewünscht",
	["Wishlist"] = "Wunschliste",
	["Wishlist alert (test)"] = "Wunschlisten-Hinweis (Test)",
	["Wishlist alerts"] = "Wunschlisten-Hinweise",
	["Wishlist first, compact rows, every quality, wishlist alerts as alert cards."] = "Wunschliste zuerst, kompakte Zeilen, jede Qualität, Wunschlisten-Hinweise als Hinweiskarten.",
	["Wishlist item"] = "Wunschlisten-Gegenstand",
	["Wishlist item found: %s"] = "Wunschlisten-Gegenstand gefunden: %s",
	["Wishlists"] = "Wunschlisten",
	["Wishlists go only to your group, your guild or friends."] = "Wunschlisten gehen nur an Eure Gruppe, Eure Gilde oder Freunde.",
	["With %s"] = "Mit %s",
	["With all checked, nothing is filtered."] = "Sind alle angehakt, wird nichts gefiltert.",
	["With upgrades for me"] = "Mit Verbesserungen für mich",
	["Wizard oil"] = "Zauberöl",
	["WoW: Forever"] = "WoW: Forever",
	["WoW: Forever has announced this instance. Its loot shows here once it opens and drops are seen."] = "WoW: Forever hat diese Instanz angekündigt. Ihre Beute erscheint hier, sobald sie öffnet und Beute gesehen wird.",
	["Won %s"] = "%s gewonnen",
	["Won with you"] = "Mit Euch gewonnen",
	["World Bosses"] = "Weltbosse",
	["World drop"] = "Weltbeute",
	["World epics"] = "Welt-Epics",
	["World event"] = "Weltereignis",
	["World events"] = "Weltereignisse",
	["World events come from EldoUI_LootData. Install it next to EldoUI to list them."] = "Weltereignisse kommen aus EldoUI_LootData. Installiert es neben EldoUI, um sie aufzulisten.",
	["World needs the loot data"] = "Welt braucht die Beutedaten",
	["Wrist"] = "Handgelenke",
	["Write a note"] = "Eine Notiz schreiben",
	["Write a note about it"] = "Eine Notiz dazu schreiben",
	["Write a note on it"] = "Eine Notiz darauf schreiben",
	["Write about this place, a reminder for later, or shift-click an item into it."] = "Schreibt über diesen Ort, eine Erinnerung für später, oder fügt mit Umschalt-Klick einen Gegenstand ein.",
	["Write down what this character does: levels, places, quests, finds, people, goals and notes. Off: the journal keeps what it has and adds nothing."] = "Schreibt auf, was dieser Charakter tut: Stufen, Orte, Quests, Funde, Leute, Ziele und Notizen. Aus: Das Tagebuch behält, was es hat, und fügt nichts hinzu.",
	["Write something first."] = "Schreibt zuerst etwas.",
	["Write the journal"] = "Tagebuch schreiben",
	["Write the names of people you grouped with. They are left out of the character card and exports unless you check them there."] = "Schreibt die Namen der Leute auf, mit denen Ihr in einer Gruppe wart. Sie bleiben aus der Charakterkarte und den Exporten heraus, außer Ihr hakt sie dort an.",
	["Write what you want to do."] = "Schreibt, was Ihr tun möchtet.",
	["Writes the note into your journal with where and when you wrote it."] = "Schreibt die Notiz in Euer Tagebuch, mit Ort und Zeit, an dem Ihr sie geschrieben habt.",
	["Writing"] = "Schreiben",
	["Written by %s on %s."] = "Geschrieben von %s am %s.",
	["You already have that standing."] = "Diesen Rang habt Ihr schon.",
	["You are %d of %d steps in."] = { one = "Ihr seid bei Schritt %d von %d.", other = "Ihr seid bei Schritt %d von %d." },
	["You are here"] = "Ihr seid hier",
	["You are here."] = "Ihr seid hier.",
	["You are level %d"] = "Ihr seid Stufe %d",
	["You are not %s."] = "Ihr seid nicht %s.",
	["You are not in Bear Form. Shift and press Sim again."] = "Ihr seid nicht in Bärengestalt. Verwandelt Euch und drückt erneut auf Sim.",
	["You are not in Cat Form. Shift and press Sim again."] = "Ihr seid nicht in Katzengestalt. Verwandelt Euch und drückt erneut auf Sim.",
	["You are not in a raid group; this is a raid of %d."] = "Ihr seid in keiner Schlachtzugsgruppe; dies ist ein Schlachtzug für %d.",
	["You are on your own; this is a %d-player dungeon."] = "Ihr seid allein; dies ist ein Dungeon für %d Spieler.",
	["You are resting: rested XP builds four times as fast here."] = "Ihr ruht: Erholungserfahrung sammelt sich hier viermal so schnell.",
	["You are saved to it until the reset."] = "Ihr seid bis zum Zurücksetzen gespeichert.",
	["You came here before the journal kept dates."] = "Ihr wart hier, bevor das Tagebuch Daten festhielt.",
	["You can learn them now."] = "Ihr könnt sie jetzt erlernen.",
	["You can take this quest now."] = "Ihr könnt diese Quest jetzt annehmen.",
	["You can't Need on this roll."] = "Bei diesem Wurf könnt Ihr nicht Bedarf wählen.",
	["You can't use this"] = "Ihr könnt das nicht benutzen",
	["You can't use this weapon type"] = "Ihr könnt diesen Waffentyp nicht benutzen",
	["You can't wear this armor"] = "Ihr könnt diese Rüstung nicht tragen",
	["You defeated one of these this session."] = "Ihr habt in dieser Sitzung einen davon besiegt.",
	["You do not have this profession."] = "Ihr habt diesen Beruf nicht.",
	["You do not know this recipe yet."] = "Ihr kennt dieses Rezept noch nicht.",
	["You finished %s; the next part is waiting."] = "Ihr habt %s abgeschlossen; der nächste Teil wartet.",
	["You have %d quests %s in your log."] = { one = "Ihr habt %d Quest %s in Eurem Questlog.", other = "Ihr habt %d Quests %s in Eurem Questlog." },
	["You have %s."] = "Ihr habt %s.",
	["You have about an hour: trips that fit it rank higher."] = "Ihr habt etwa eine Stunde: Reisen, die dazu passen, stehen höher.",
	["You have about half an hour: trips that fit it rank higher."] = "Ihr habt etwa eine halbe Stunde: Reisen, die dazu passen, stehen höher.",
	["You have about two hours: trips that fit it rank higher."] = "Ihr habt etwa zwei Stunden: Reisen, die dazu passen, stehen höher.",
	["You have already done that quest."] = "Diese Quest habt Ihr schon erledigt.",
	["You have already finished that quest chain."] = "Diese Questreihe habt Ihr schon abgeschlossen.",
	["You have been here %d times."] = { one = "Ihr wart %d Mal hier.", other = "Ihr wart %d Mal hier." },
	["You have been here."] = "Ihr wart schon hier.",
	["You have done this quest."] = "Ihr habt diese Quest erledigt.",
	["You have not been inside yet."] = "Ihr wart noch nicht drinnen.",
	["You have not grouped on this character yet; your player notes know them."] = "Ihr wart mit diesem Charakter noch in keiner Gruppe; Eure Spielernotizen kennen sie.",
	["You have not met this faction yet."] = "Diese Fraktion habt Ihr noch nicht kennengelernt.",
	["You have run dungeons with %s adventurers."] = { one = "Ihr habt mit %s Abenteurer Dungeons besucht.", other = "Ihr habt mit %s Abenteurern Dungeons besucht." },
	["You have shared the road with %s adventurers, %s in all."] = { one = "Ihr habt den Weg mit %s Abenteurer geteilt, insgesamt %s.", other = "Ihr habt den Weg mit %s Abenteurern geteilt, insgesamt %s." },
	["You have them all."] = "Ihr habt sie alle.",
	["You imported before: only what is new since then comes in."] = "Ihr habt schon einmal importiert: Nur was seitdem neu ist, kommt herein.",
	["You know this recipe."] = "Ihr kennt dieses Rezept.",
	["You left %s with a quest unfinished."] = "Ihr habt %s mit einer unfertigen Quest verlassen.",
	["You missed one"] = "Ihr habt einen verpasst",
	["You need %d skill to learn it."] = "Ihr braucht Fertigkeit %d, um es zu erlernen.",
	["You own something better"] = "Ihr besitzt etwas Besseres",
	["You ran dungeons together before the journal kept company."] = "Ihr wart zusammen in Dungeons, bevor das Tagebuch Gefährten festhielt.",
	["You ran it %d times at this level."] = { one = "Ihr wart einmal auf dieser Stufe darin.", other = "Ihr wart %d Mal auf dieser Stufe darin." },
	["You rate items with the simulator: this runs your Best in Slot set now (out of combat, in small steps)."] = "Ihr bewertet Gegenstände mit dem Simulator: Dies lässt jetzt Euer Best-in-Slot-Set laufen (außerhalb des Kampfes, in kleinen Schritten).",
	["You wear this item"] = "Ihr tragt diesen Gegenstand",
	["You were away %s."] = "Ihr wart %s weg.",
	["You were away %s. You left off in %s at level %d."] = "Ihr wart %s weg. Ihr habt in %s auf Stufe %d aufgehört.",
	["You were away %s. You left off in %s."] = "Ihr wart %s weg. Ihr habt in %s aufgehört.",
	["Your /played time, from the game."] = "Eure /played-Zeit, vom Spiel.",
	["Your Best in Slot run is outdated."] = "Euer Best-in-Slot-Durchlauf ist veraltet.",
	["Your DPS with what you wear, the damage of each ability, what one more point of each stat is worth, and what the simulator read."] = "Eure DPS mit Eurer Ausrüstung, der Schaden jeder Fähigkeit, was ein Punkt mehr in jedem Wert bringt und was der Simulator gelesen hat.",
	["Your DPS: %.1f ± %.1f (estimate)"] = "Eure DPS: %.1f ± %.1f (Schätzung)",
	["Your Forever Journal history for this character is now in My Adventure (%s)."] = "Eure Forever-Journal-Geschichte für diesen Charakter ist jetzt in Mein Abenteuer (%s).",
	["Your active goals under the quest tracker. Click a to-do to check it."] = "Eure aktiven Ziele unter dem Questtracker. Klickt auf eine Aufgabe, um sie abzuhaken.",
	["Your active wishlist by slot. Click a slot to choose its main pick; the model wears the picks."] = "Eure aktive Wunschliste nach Platz. Klickt auf einen Platz, um seine Hauptwahl zu treffen; das Modell trägt die Wahl.",
	["Your active wishlist has no gear. Star items in the Journal or Search; they show here by slot."] = "Eure aktive Wunschliste hat keine Ausrüstung. Markiert Gegenstände im Tagebuch oder in der Suche mit einem Stern; sie erscheinen hier nach Platz.",
	["Your big moments as cards: first kills, epic finds, standings, mounts, and the moments you kept, with your firsts."] = "Eure großen Momente als Karten: erste Siege, epische Funde, Ränge, Reittiere und die Momente, die Ihr aufgehoben habt, mit Euren Ersten.",
	["Your big moments at these levels."] = "Eure großen Momente auf diesen Stufen.",
	["Your character card"] = "Eure Charakterkarte",
	["Your character card as Markdown"] = "Eure Charakterkarte als Markdown",
	["Your character card as a few lines of text. Companion names are left out."] = "Eure Charakterkarte als ein paar Zeilen Text. Namen von Gefährten bleiben weg.",
	["Your character card on a dimmed screen, ready for your own screenshot key."] = "Eure Charakterkarte auf abgedunkeltem Bildschirm, bereit für Eure eigene Screenshot-Taste.",
	["Your character's journal in the Journal window: a diary that writes itself, keepsakes, places, quests, goals and notes, your story from 1 to 60 and where to go next."] = "Das Tagebuch Eures Charakters im Tagebuchfenster: eine Chronik, die sich selbst schreibt, Andenken, Orte, Quests, Ziele und Notizen, Eure Geschichte von 1 bis 60 und wohin als Nächstes.",
	["Your character's journal, the first tab of this window: where to go next, what is waiting for you, and everything you have done."] = "Das Tagebuch Eures Charakters, der erste Reiter dieses Fensters: wohin als Nächstes, was auf Euch wartet und alles, was Ihr getan habt.",
	["Your character's journal: what you did and where, keepsakes, goals, notes, attunements, and where to go next."] = "Das Tagebuch Eures Charakters: was Ihr wo getan habt, Andenken, Ziele, Notizen, Einstimmungen und wohin als Nächstes.",
	["Your character's journal: where to go next, what is waiting for you, your goals and notes, and the story so far. /eui tour journal shows it part by part."] = "Das Tagebuch Eures Charakters: wohin als Nächstes, was auf Euch wartet, Eure Ziele und Notizen und die Geschichte bisher. /eui tour journal zeigt es Teil für Teil.",
	["Your character's story in a few lines, with the level river, your numbers, the eras, and ways to share it."] = "Die Geschichte Eures Charakters in ein paar Zeilen, mit dem Stufenfluss, Euren Zahlen, den Zeitaltern und Wegen, sie zu teilen.",
	["Your character's story in a few pages."] = "Die Geschichte Eures Charakters auf ein paar Seiten.",
	["Your characters"] = "Eure Charaktere",
	["Your characters and how far each one is (Alts module)."] = "Eure Charaktere und wie weit jeder ist (Modul Charaktere).",
	["Your class (Sets for my class only), all classes or one other class."] = "Eure Klasse (Sets nur für meine Klasse), alle Klassen oder eine andere Klasse.",
	["Your class can't use it"] = "Eure Klasse kann es nicht benutzen",
	["Your class can't use this"] = "Eure Klasse kann das nicht benutzen",
	["Your factions with your standing. Pick one to see what it sells and gives at each standing."] = "Eure Fraktionen mit Eurem Rang. Wählt eine, um zu sehen, was sie auf jedem Rang verkauft und gibt.",
	["Your filters hide all %d drops."] = { one = "Eure Filter blenden %d Beutestück aus.", other = "Eure Filter blenden alle %d Beutestücke aus." },
	["Your filters hide every attunement. Show finished attunements?"] = "Eure Filter blenden jede Einstimmung aus. Erledigte Einstimmungen zeigen?",
	["Your first attunement step is open:"] = "Euer erster Einstimmungsschritt ist offen:",
	["Your first attunement step."] = "Euer erster Einstimmungsschritt.",
	["Your first boss kill."] = "Euer erster Bosssieg.",
	["Your first dungeon is waiting. These fit your level:"] = "Euer erster Dungeon wartet. Diese passen zu Eurer Stufe:",
	["Your first epic find."] = "Euer erster epischer Fund.",
	["Your first mount comes from your race's mount vendor once you have the level and the gold it asks for."] = "Euer erstes Reittier gibt es beim Reittierhändler Eures Volkes, sobald Ihr die verlangte Stufe und das Gold habt.",
	["Your first mount comes from your race's mount vendor once you have the level and the gold it asks for. Meanwhile:"] = "Euer erstes Reittier gibt es beim Reittierhändler Eures Volkes, sobald Ihr die verlangte Stufe und das Gold habt. Bis dahin:",
	["Your first mount."] = "Euer erstes Reittier.",
	["Your gear is better for %s"] = "Eure Ausrüstung ist besser für %s",
	["Your group"] = "Eure Gruppe",
	["Your group is small for a %d-player dungeon."] = "Eure Gruppe ist klein für einen Dungeon für %d Spieler.",
	["Your hearthstone is set to %s."] = "Euer Ruhestein ist auf %s gesetzt.",
	["Your honor, marks and rank. Costs show once you have visited the vendor."] = "Eure Ehre, Abzeichen und Rang. Kosten erscheinen, sobald Ihr den Händler besucht habt.",
	["Your journal as it is now is backed up first either way."] = "Euer Tagebuch, wie es jetzt ist, wird in jedem Fall zuerst gesichert.",
	["Your journal is back as it was then."] = "Euer Tagebuch ist wieder so wie damals.",
	["Your journal starts today"] = "Euer Tagebuch beginnt heute",
	["Your last run took %s."] = "Euer letzter Durchlauf dauerte %s.",
	["Your level"] = "Eure Stufe",
	["Your levels while you were grouped with them."] = "Eure Stufen, während Ihr mit ihnen in einer Gruppe wart.",
	["Your loot journal, Best in Slot planner and wishlist in one window. This short tour shows each part; Skip ends it, and Start tour on the settings page brings it back."] = "Euer Beutetagebuch, Best-in-Slot-Planer und Wunschliste in einem Fenster. Diese kurze Tour zeigt jeden Teil; Überspringen beendet sie und Tour starten auf der Einstellungsseite bringt sie zurück.",
	["Your loot list"] = "Eure Beuteliste",
	["Your name, or the pronoun you pick. Exports always use your name."] = "Euer Name oder das Pronomen, das Ihr wählt. Exporte nutzen immer Euren Namen.",
	["Your note on \"%s\" (up to %d letters; empty removes it):"] = "Eure Notiz zu \"%s\" (bis zu %d Zeichen; leer entfernt sie):",
	["Your note on them, kept in Player Notes and shown on their tooltip."] = "Eure Notiz zu ihnen, gespeichert in Spielernotizen und in ihrem Tooltip gezeigt.",
	["Your note, from Player Notes"] = "Eure Notiz, aus Spielernotizen",
	["Your note: %s"] = "Eure Notiz: %s",
	["Your notes."] = "Eure Notizen.",
	["Your own level times show here once you have a few levels behind you."] = "Eure eigenen Stufenzeiten erscheinen hier, sobald Ihr ein paar Stufen hinter Euch habt.",
	["Your own plan. Click a slot to pick items; right-click the chip to rename it."] = "Euer eigener Plan. Klickt auf einen Platz, um Gegenstände zu wählen; Rechtsklick auf den Chip benennt ihn um.",
	["Your own side's factions, or the other side's (to see what they get)."] = "Die Fraktionen Eurer eigenen Seite oder die der anderen Seite (um zu sehen, was sie bekommen).",
	["Your pet is not out. Call it and press Sim again."] = "Euer Begleiter ist nicht draußen. Ruft ihn und drückt erneut auf Sim.",
	["Your plan sets are empty. Pick items for them on the Best in Slot page or in the Planner tab."] = "Eure Plansets sind leer. Wählt Gegenstände dafür auf der Seite Best in Slot oder im Reiter Planer.",
	["Your plan sets are shared with the Best in Slot page. Rename them there."] = "Eure Plansets werden mit der Seite Best in Slot geteilt. Benennt sie dort um.",
	["Your professions come first with your skill. Open your profession window once so known recipes and their colors show."] = "Eure Berufe stehen mit Eurer Fertigkeit vorne. Öffnet Euer Berufsfenster einmal, damit bekannte Rezepte und ihre Farben erscheinen.",
	["Your quest log is empty"] = "Euer Questlog ist leer",
	["Your quest log now, with where and when you took each quest."] = "Euer Questlog jetzt, mit Ort und Zeit, an dem Ihr jede Quest angenommen habt.",
	["Your quests here: %s."] = { one = "Eure Quest hier: %s.", other = "Eure Quests hier: %s." },
	["Your race can't use it"] = "Euer Volk kann es nicht benutzen",
	["Your runs"] = "Eure Durchläufe",
	["Your runs are back as they were then."] = "Eure Durchläufe sind wieder so wie damals.",
	["Your runs as one code, to keep or to paste in on another PC. Nothing is sent anywhere."] = "Eure Durchläufe als ein Code, zum Aufbewahren oder zum Einfügen auf einem anderen PC. Nichts wird irgendwohin gesendet.",
	["Your runs as they are now are backed up first either way."] = "Eure Durchläufe, wie sie jetzt sind, werden in jedem Fall zuerst gesichert.",
	["Your runs here: first visit, time inside, bosses beaten, who came along, and what is still to do."] = "Eure Durchläufe hier: erster Besuch, Zeit drinnen, besiegte Bosse, wer dabei war und was noch zu tun ist.",
	["Your runs there"] = "Eure Durchläufe dort",
	["Your screenshot key: %s."] = "Eure Screenshot-Taste: %s.",
	["Your sets are simulated. Open the Sets tab to compare them."] = "Eure Sets sind simuliert. Öffnet den Reiter Sets, um sie zu vergleichen.",
	["Your side"] = "Eure Seite",
	["Your skill: %d"] = "Eure Fertigkeit: %d",
	["Your spec, the armor you wear and where gear may come from. This one list counts everywhere: For You, tooltips and roll advice."] = "Eure Spezialisierung, die Rüstung, die Ihr tragt, und woher Ausrüstung kommen darf. Diese eine Liste zählt überall: Für Euch, Tooltips und Würfelratschläge.",
	["Your story as Markdown"] = "Eure Geschichte als Markdown",
	["Your story as it happened: chapters by level, day, or zone, with keepsakes, finds, and pinned notes."] = "Eure Geschichte, wie sie geschah: Kapitel nach Stufe, Tag oder Gebiet, mit Andenken, Funden und angehefteten Notizen.",
	["Your story as text"] = "Eure Geschichte als Text",
	["Your story chapter by chapter: levels, places, first kills, finds, and the people you met. Keepsakes and the story so far sit beside it."] = "Eure Geschichte Kapitel für Kapitel: Stufen, Orte, erste Siege, Funde und die Leute, die Ihr getroffen habt. Andenken und die Geschichte bisher stehen daneben.",
	["Your story from level 1 to 60 as a book in chapters, in the tone you choose, with a cover for every part."] = "Eure Geschichte von Stufe 1 bis 60 als Buch in Kapiteln, im Tonfall Eurer Wahl, mit einem Umschlag für jeden Teil.",
	["Your story in chapters, page by page."] = "Eure Geschichte in Kapiteln, Seite für Seite.",
